const lessons = [
{"num": 3, "time": "00:01:00,000 --> 00:01:38,560", "arabic": "تَأْمُرُ بِالْمَعْرُوفِ وَتَنْهَى عَنِ الْمُنْكَرِ وَيَجْتَمِعُ حَوْلَكَ النَّاسُ وَيُبَايِعُونَكَ عَلَى ذَلِكَ، وَكُلُّ هَذَا لَا أَكْتَرِثُ لَهُ وَلَيْسَ لِي عَلَيْكَ فِيهِ غَضَبٌ.", "segs": [{"ar": "تَأْمُرُ بِالْمَعْرُوفِ وَتَنْهَى عَنِ الْمُنْكَرِ", "uz": "Sen yaxshilikka buyurasan, yomonlikdan qaytarasan,"}, {"ar": "وَيَجْتَمِعُ حَوْلَكَ النَّاسُ وَيُبَايِعُونَكَ عَلَى ذَلِكَ،", "uz": "odamlar atrofingga to'planib, senga shu haqda bay'at qilishadi"}, {"ar": "وَكُلُّ هَذَا لَا أَكْتَرِثُ لَهُ", "uz": "— bularning barchasiga ahamiyat bermayman va"}, {"ar": "وَلَيْسَ لِي عَلَيْكَ فِيهِ غَضَبٌ.", "uz": "bu borada sendan g'azabim yo'q."}], "full_uz": "Sen yaxshilikka buyurasan, yomonlikdan qaytarasan, odamlar atrofingga to'planib, senga shu haqda bay'at qilishadi — bularning barchasiga ahamiyat bermayman va bu borada sendan g'azabim yo'q.", "note": null},
{"num": 9, "time": "00:01:38,560 --> 00:02:05,780", "arabic": "أَخْبِرْنِي عَنِ الْقُرْآنِ الْكَرِيمِ: هُوَ كَلَامُ اللَّهِ، أَوْحَاهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَنَزَلَ بِهِ جِبْرِيلُ عَلَى قَلْبِهِ، أَمَخْلُوقٌ هُوَ؟", "segs": [{"ar": "أَخْبِرْنِي عَنِ الْقُرْآنِ الْكَرِيمِ: هُوَ كَلَامُ اللَّهِ،", "uz": "Menga Qur'oni Karim haqida ayt: u Allohning kalomi,"}, {"ar": "أَوْحَاهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،", "uz": "Rasululloh (sollallohu alayhi va sallam)ga vahiy qilingan,"}, {"ar": "وَنَزَلَ بِهِ جِبْرِيلُ عَلَى قَلْبِهِ،", "uz": "Jabroil uni uning qalbiga tushirgan. Yaratilganmi"}, {"ar": "أَمَخْلُوقٌ هُوَ؟", "uz": "u?"}], "full_uz": "Menga Qur'oni Karim haqida ayt: u Allohning kalomi, Rasululloh (sollallohu alayhi va sallam)ga vahiy qilingan, Jabroil uni uning qalbiga tushirgan. Yaratilganmi u?", "note": null},
{"num": 14, "time": "00:02:12,819 --> 00:02:13,560", "arabic": "قُلْ.", "segs": null, "full_uz": "Ayt.", "note": null},
{"num": 15, "time": "00:02:13,560 --> 00:02:16,700", "arabic": "هُوَ كَلَامُ اللَّهِ.", "segs": null, "full_uz": "U Allohning kalomidir.", "note": null},
{"num": 16, "time": "00:02:16,700 --> 00:02:24,879", "arabic": "أَعْلَمُ أَنَّهُ كَلَامُ اللَّهِ، أَهُوَ مَخْلُوقٌ أَمْ لَا؟", "segs": null, "full_uz": "Uning Allohning kalomi ekanini bilaman, yaratilganmi yoki yo'qmi?", "note": null},
{"num": 18, "time": "00:02:24,879 --> 00:02:29,299", "arabic": "هُوَ كَلَامُ اللَّهِ غَيْرُ مَخْلُوقٍ.", "segs": null, "full_uz": "U Allohning yaratilmagan kalomidir.", "note": null},
{"num": 20, "time": "00:02:29,299 --> 00:02:37,719", "arabic": "بَلَغَنِي أَنَّكَ تَزْعُمُ أَنَّ لِلَّهِ أَصَابِعَ.", "segs": null, "full_uz": "Menga yetib keldiki, sen Allohning barmoqlari bor deb da'vo qilyapsan.", "note": null},
{"num": 21, "time": "00:02:37,719 --> 00:02:46,099", "arabic": "إِنَّمَا نُثْبِتُ لِلَّهِ مَا أَثْبَتَهُ لِذَاتِهِ وَنَنْفِي عَنْهُ مَا نَفَاهُ عَنْ ذَاتِهِ سُبْحَانَهُ وَتَعَالَى.", "segs": [{"ar": "إِنَّمَا نُثْبِتُ لِلَّهِ مَا أَثْبَتَهُ لِذَاتِهِ", "uz": "Biz faqat Alloh O'zi uchun isbotlagan narsani isbotlaymiz va"}, {"ar": "وَنَنْفِي عَنْهُ مَا نَفَاهُ عَنْ ذَاتِهِ سُبْحَانَهُ وَتَعَالَى.", "uz": "U pok va oliy Zot O'zidan nafiy qilgan narsani nafiy qilamiz."}], "full_uz": "Biz faqat Alloh O'zi uchun isbotlagan narsani isbotlaymiz va U pok va oliy Zot O'zidan nafiy qilgan narsani nafiy qilamiz.", "note": null},
{"num": 23, "time": "00:02:46,099 --> 00:03:01,920", "arabic": "وَقَدْ حَدَّثَنِي الْإِمَامُ سُفْيَانُ بْنُ عُيَيْنَةَ بِحَدِيثٍ يَرْفَعُهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ قَلْبَ بَنِي آدَمَ بَيْنَ إِصْبَعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ.", "segs": [{"ar": "وَقَدْ حَدَّثَنِي الْإِمَامُ سُفْيَانُ", "uz": "Imom Sufyon ibn Uyayna"}, {"ar": "بْنُ عُيَيْنَةَ بِحَدِيثٍ", "uz": "menga Rasululloh (sollallohu"}, {"ar": "يَرْفَعُهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ", "uz": "alayhi va sallam)ga borib taqaladigan bir hadisni"}, {"ar": "وَسَلَّمَ قَالَ: إِنَّ قَلْبَ بَنِي آدَمَ", "uz": "rivoyat qilib berdi: \"Odam bolasining qalbi"}, {"ar": "بَيْنَ إِصْبَعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ.", "uz": "Rahmonning ikki barmog'i orasidadir.\""}], "full_uz": "Imom Sufyon ibn Uyayna menga Rasululloh (sollallohu alayhi va sallam)ga borib taqaladigan bir hadisni rivoyat qilib berdi: \"Odam bolasining qalbi Rahmonning ikki barmog'i orasidadir.\"", "note": "Sahih Muslimdagi hadisga ishora — Allohning sifatlariga oid, ilohiyotchilar orasida turlicha talqin qilingan matnlardan biri."},
{"num": 26, "time": "00:03:01,920 --> 00:03:09,580", "arabic": "إِذَنْ أَنْتَ مُقِرٌّ بِإِنْكَارِ خَلْقِ الْقُرْآنِ وَإِثْبَاتِ الرُّؤْيَةِ وَالتَّجْسِيمِ لِلَّهِ عَزَّ وَجَلَّ؟", "segs": [{"ar": "إِذَنْ أَنْتَ مُقِرٌّ بِإِنْكَارِ خَلْقِ الْقُرْآنِ", "uz": "Unda sen Qur'onning yaratilganligini inkor etib,"}, {"ar": "وَإِثْبَاتِ الرُّؤْيَةِ وَالتَّجْسِيمِ لِلَّهِ عَزَّ وَجَلَّ؟", "uz": "Allohni ko'rishni va Unga jism nisbat berishni tan olyapsanmi?"}], "full_uz": "Unda sen Qur'onning yaratilganligini inkor etib, Allohni ko'rishni va Unga jism nisbat berishni tan olyapsanmi?", "note": null},
{"num": 27, "time": "00:03:09,580 --> 00:03:13,080", "arabic": "إِنَّمَا أَقْرَأُ عَلَيْكَ مَا جَاءَ فِي الْقُرْآنِ وَالْحَدِيثِ.", "segs": null, "full_uz": "Men senga faqat Qur'on va hadisda kelgan narsani o'qib beryapman.", "note": null},
{"num": 28, "time": "00:03:19,960 --> 00:03:23,640", "arabic": "وَيْحَكَ، كُنْتَ فِيمَا تَقُولُ أَيُّهَا الرَّجُلُ.", "segs": null, "full_uz": "Voy senga, aytganingda [sodiq/mustahkam] eding, odam bola.", "note": null},
{"num": 29, "time": "00:03:23,639 --> 00:03:26,039", "arabic": "أَنْتَ أَمَرْتَنِي بِذَلِكَ.", "segs": null, "full_uz": "Sen menga shuni buyurgan eding.", "note": null},
{"num": 30, "time": "00:03:26,039 --> 00:03:28,579", "arabic": "أَنَا أَمَرْتُكَ؟ أَجَلْ.", "segs": null, "full_uz": "Men senga buyurdimmi? Ha.", "note": null},
{"num": 32, "time": "00:03:28,579 --> 00:03:33,639", "arabic": "أَلَمْ تَقُلْ لِي: كَانَ يَجْدُرُ بِكَ أَنْ تَنْصَحَ لِإِمَامِكَ؟", "segs": null, "full_uz": "Menga: \"Imomingga nasihat berishing kerak edi\" demaganmiding?", "note": null},
{"num": 34, "time": "00:03:34,419 --> 00:03:45,719", "arabic": "مَا تَقُولُونَ فِي هَذَا الرَّجُلِ؟", "segs": null, "full_uz": "Bu odam haqida nima deysizlar?", "note": null},
{"num": 38, "time": "00:05:23,639 --> 00:05:45,279", "arabic": "مَوْلَايَ.", "segs": null, "full_uz": "Xo'jayinim.", "note": null},
{"num": 39, "time": "00:05:45,279 --> 00:05:54,519", "arabic": "قَدْ نَطَقَ الرَّجُلُ بِكَلِمَةِ الْكُفْرِ، وَرَأْيِي اسْتِتَابَتُهُ.", "segs": null, "full_uz": "Bu odam kufr so'zini aytdi, fikrimcha uni tavbaga chaqirish kerak.", "note": null},
{"num": 41, "time": "00:05:54,519 --> 00:06:01,419", "arabic": "لَعَلَّ بِهِ عَاهَةً أَوْ نَقْصَ عَقْلٍ.", "segs": null, "full_uz": "Balki unda biror nuqson yoki aqli kamlik bordir.", "note": null},
{"num": 43, "time": "00:06:01,419 --> 00:06:11,719", "arabic": "كَذَبْتَ وَاللَّهِ، فَأَنْتَ تَعْلَمُ عِلْمَ الْيَقِينِ أَنَّ مَا بِي عَاهَةٌ وَلَا نَقْصُ عَقْلٍ، وَمَا أَنَا مِنَ الْكَافِرِينَ.", "segs": [{"ar": "كَذَبْتَ وَاللَّهِ،", "uz": "Vallohi,"}, {"ar": "فَأَنْتَ تَعْلَمُ عِلْمَ الْيَقِينِ أَنَّ مَا بِي عَاهَةٌ وَلَا نَقْصُ عَقْلٍ،", "uz": "yolg'on aytding, sen aniq bilasanki, menda na nuqson, na aqli kamlik bor,"}, {"ar": "وَمَا أَنَا مِنَ الْكَافِرِينَ.", "uz": "va men kofirlardan emasman."}], "full_uz": "Vallohi, yolg'on aytding, sen aniq bilasanki, menda na nuqson, na aqli kamlik bor, va men kofirlardan emasman.", "note": null},
{"num": 47, "time": "00:06:11,719 --> 00:06:17,019", "arabic": "إِنَّمَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ.", "segs": [{"ar": "إِنَّمَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ", "uz": "Men faqat Allohdan boshqa iloh yo'qligiga va Muhammad"}, {"ar": "وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ.", "uz": "Uning Rasuli ekaniga guvohlik beraman."}], "full_uz": "Men faqat Allohdan boshqa iloh yo'qligiga va Muhammad Uning Rasuli ekaniga guvohlik beraman.", "note": null},
{"num": 49, "time": "00:06:17,019 --> 00:06:23,359", "arabic": "وَمَا أَنْتَ مِنْ أَهْلِ الْعِلْمِ وَأَصْحَابِ الْفُتْيَا حَتَّى تُفْتِيَ بِذَلِكَ.", "segs": [{"ar": "وَمَا أَنْتَ مِنْ أَهْلِ الْعِلْمِ", "uz": "Sen bunday fatvo berishga ilm"}, {"ar": "وَأَصْحَابِ الْفُتْيَا حَتَّى تُفْتِيَ بِذَلِكَ.", "uz": "ahli va fatvo egalaridan emassan."}], "full_uz": "Sen bunday fatvo berishga ilm ahli va fatvo egalaridan emassan.", "note": null},
{"num": 51, "time": "00:06:23,359 --> 00:06:33,279", "arabic": "وَقَدْ جَاءَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: مَنْ قَالَ لِأَخِيهِ يَا كَافِرُ فَقَدْ بَاءَ بِهَا أَحَدُهُمَا.", "segs": [{"ar": "وَقَدْ جَاءَ عَنْ رَسُولِ", "uz": "Rasululloh (sollallohu alayhi va"}, {"ar": "اللَّهِ صَلَّى اللَّهُ عَلَيْهِ", "uz": "sallam)dan rivoyat qilingan: \"Kim"}, {"ar": "وَسَلَّمَ أَنَّهُ قَالَ: مَنْ قَالَ لِأَخِيهِ يَا كَافِرُ", "uz": "o'z birodariga 'ey kofir' desa,"}, {"ar": "فَقَدْ بَاءَ بِهَا أَحَدُهُمَا.", "uz": "bu so'z ikkisidan biriga qaytadi.\""}], "full_uz": "Rasululloh (sollallohu alayhi va sallam)dan rivoyat qilingan: \"Kim o'z birodariga 'ey kofir' desa, bu so'z ikkisidan biriga qaytadi.\"", "note": "Sahih Buxoriy va Muslimdagi hadis."},
{"num": 54, "time": "00:06:33,279 --> 00:06:36,759", "arabic": "اسْقِنِي دَمَهُ يَا أَمِيرَ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Uning qonini menga ichir, ey mo'minlar amiri.", "note": null},
{"num": 55, "time": "00:06:36,759 --> 00:06:39,560", "arabic": "فَهُوَ كَافِرٌ بِصَرِيحِ اللِّسَانِ.", "segs": null, "full_uz": "U ochiq tili bilan kofirdir.", "note": null},
{"num": 56, "time": "00:06:39,560 --> 00:06:44,060", "arabic": "وَأَنْتَ كَذَبْتَ أَيْضًا، وَلَا يَحِلُّ لَكَ شُرْبُ دَمِي.", "segs": null, "full_uz": "Sen ham yolg'on aytding, va mening qonimni ichishing senga halol emas.", "note": null},
{"num": 58, "time": "00:06:44,060 --> 00:06:53,739", "arabic": "لِأَنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ: حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنْزِيرِ.", "segs": [{"ar": "لِأَنَّ اللَّهَ عَزَّ", "uz": "Chunki Alloh azza va"}, {"ar": "وَجَلَّ قَالَ: حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنْزِيرِ.", "uz": "jalla aytadi: \"Sizlarga o'lik hayvon, qon va cho'chqa go'shti harom qilindi.\""}], "full_uz": "Chunki Alloh azza va jalla aytadi: \"Sizlarga o'lik hayvon, qon va cho'chqa go'shti harom qilindi.\"", "note": "Qur'on, Moida surasi, 3-oyat."},
{"num": 60, "time": "00:06:53,739 --> 00:07:22,179", "arabic": "أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ.", "segs": [{"ar": "أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ", "uz": "Guvohlik beramanki, Allohdan boshqa iloh yo'q"}, {"ar": "وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ.", "uz": "va Muhammad Uning Rasulidir."}], "full_uz": "Guvohlik beramanki, Allohdan boshqa iloh yo'q va Muhammad Uning Rasulidir.", "note": null},
{"num": 65, "time": "00:08:10,839 --> 00:08:15,839", "arabic": "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ.", "segs": null, "full_uz": "Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz.", "note": "Qur'on, Baqara surasi, 156-oyat."},
{"num": 66, "time": "00:08:17,839 --> 00:08:33,839", "arabic": "وَاعَجَبَاهُ، أَنْ يَمُوتَ أَمْثَالُ الْخُزَاعِيِّ عَلَى الْحَقِّ، وَلَيْتَ أَنَّ قَاتِلَهُ رَاعَى حُرْمَةَ الْمَيِّتِ، وَدَفَنَهُ كَغَيْرِهِ مِنْ عَامَّةِ الْمُسْلِمِينَ.", "segs": [{"ar": "وَاعَجَبَاهُ، أَنْ يَمُوتَ أَمْثَالُ الْخُزَاعِيِّ عَلَى الْحَقِّ،", "uz": "Naqadar hayronki, al-Xuzoiyga o'xshash odamlar haq ustida o'lishi kerak bo'ldi. Qani edi,"}, {"ar": "وَلَيْتَ أَنَّ قَاتِلَهُ رَاعَى حُرْمَةَ الْمَيِّتِ،", "uz": "uning qotili o'liklarning hurmatini saqlab,"}, {"ar": "وَدَفَنَهُ كَغَيْرِهِ مِنْ عَامَّةِ الْمُسْلِمِينَ.", "uz": "uni oddiy musulmonlar kabi dafn qilganida."}], "full_uz": "Naqadar hayronki, al-Xuzoiyga o'xshash odamlar haq ustida o'lishi kerak bo'ldi. Qani edi, uning qotili o'liklarning hurmatini saqlab, uni oddiy musulmonlar kabi dafn qilganida.", "note": null},
{"num": 69, "time": "00:08:34,839 --> 00:08:39,839", "arabic": "إِلَى مَتَى تَسْتَمِرُّ هَذِهِ الْمِحْنَةُ يَا أَبَا بَكْرٍ؟ أَمَا لَهَا مِنْ نِهَايَةٍ؟", "segs": [{"ar": "إِلَى مَتَى تَسْتَمِرُّ هَذِهِ الْمِحْنَةُ يَا", "uz": "Bu sinov qachongacha davom etadi,"}, {"ar": "أَبَا بَكْرٍ؟ أَمَا لَهَا مِنْ نِهَايَةٍ؟", "uz": "ey Abu Bakr? Uning oxiri yo'qmi?"}], "full_uz": "Bu sinov qachongacha davom etadi, ey Abu Bakr? Uning oxiri yo'qmi?", "note": null},
{"num": 71, "time": "00:08:39,840 --> 00:08:43,840", "arabic": "إِلَى أَنْ يَشَاءَ اللَّهُ يَا صَالِحُ.", "segs": null, "full_uz": "Alloh xohlaguncha, Solih.", "note": null},
{"num": 73, "time": "00:08:43,840 --> 00:08:47,840", "arabic": "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ.", "segs": null, "full_uz": "Alloh bizga kifoya qiladi, U qanday ham yaxshi vakildir.", "note": null},
{"num": 75, "time": "00:08:47,840 --> 00:09:03,840", "arabic": "أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ؟ وَلَقَدْ فَتَنَّا الَّذِينَ مِنْ قَبْلِهِمْ فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ صَدَقُوا وَلَيَعْلَمَنَّ الْكَاذِبِينَ.", "segs": [{"ar": "أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا", "uz": "Odamlar, biz iymon keltirdik, deyishlari bilanoq, sinovsiz qoldirilishlarini o'ylaydilarmi?"}, {"ar": "وَهُمْ لَا يُفْتَنُونَ؟", "uz": "Albatta,"}, {"ar": "وَلَقَدْ فَتَنَّا الَّذِينَ مِنْ قَبْلِهِمْ", "uz": "Biz ulardan avvalgilarni ham sinaganmiz. Alloh haqiqatan kim"}, {"ar": "فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ صَدَقُوا وَلَيَعْلَمَنَّ الْكَاذِبِينَ.", "uz": "rost so'zlaganini va kim yolg'onchilarni albatta biladi."}], "full_uz": "Odamlar, biz iymon keltirdik, deyishlari bilanoq, sinovsiz qoldirilishlarini o'ylaydilarmi? Albatta, Biz ulardan avvalgilarni ham sinaganmiz. Alloh haqiqatan kim rost so'zlaganini va kim yolg'onchilarni albatta biladi.", "note": "Qur'on, Ankabut surasi, 2-3-oyatlar."},
{"num": 81, "time": "00:09:39,840 --> 00:09:42,800", "arabic": "مَوْلَايَ.", "segs": null, "full_uz": "Xo'jayinim.", "note": null},
{"num": 82, "time": "00:09:42,800 --> 00:09:46,759", "arabic": "مَا الَّذِي يَشْغَلُكَ يَا جَعْفَرُ؟", "segs": null, "full_uz": "Seni nima band qilyapti, Ja'far?", "note": null},
{"num": 83, "time": "00:09:46,759 --> 00:09:48,060", "arabic": "أَشْيَاءُ يَا أَبَا جَعْفَرٍ.", "segs": null, "full_uz": "Ba'zi narsalar, ey Abu Ja'far.", "note": null},
{"num": 84, "time": "00:09:48,060 --> 00:09:58,759", "arabic": "هَلْ أَنْتَ رَاضٍ عَمَّا فَعَلَهُ أَخُوكَ يَا جَعْفَرُ؟", "segs": null, "full_uz": "Akangiz qilgan ishdan rozimisiz, Ja'far?", "note": null},
{"num": 85, "time": "00:09:58,759 --> 00:10:02,660", "arabic": "أَمِيرُ الْمُؤْمِنِينَ أَعْلَمُ مِنِّي بِمَا هُوَ أَصْلَحُ لَهُ فِي دِينِهِ وَدُنْيَاهُ.", "segs": [{"ar": "أَمِيرُ الْمُؤْمِنِينَ أَعْلَمُ مِنِّي بِمَا هُوَ أَصْلَحُ لَهُ فِي دِينِهِ", "uz": "Mo'minlar amiri o'z dini va dunyosi uchun nima yaxshiroq ekanini mendan yaxshiroq"}, {"ar": "وَدُنْيَاهُ.", "uz": "biladi."}], "full_uz": "Mo'minlar amiri o'z dini va dunyosi uchun nima yaxshiroq ekanini mendan yaxshiroq biladi.", "note": null},
{"num": 86, "time": "00:10:02,660 --> 00:10:05,220", "arabic": "أَسْتَأْذِنُكَ يَا مَوْلَايَ.", "segs": null, "full_uz": "Ijozat so'rayman, xo'jayinim.", "note": null},
{"num": 87, "time": "00:10:05,220 --> 00:10:08,639", "arabic": "جَعْفَرُ.", "segs": null, "full_uz": "Ja'far.", "note": null},
{"num": 88, "time": "00:10:08,639 --> 00:10:20,740", "arabic": "أَصْدِقْنِي الْقَوْلَ، وَلَا أُرِيدُكَ إِلَّا صَادِقًا.", "segs": null, "full_uz": "Menga rost gapir, va sendan faqat sodiqlikni istayman.", "note": null},
{"num": 90, "time": "00:10:20,740 --> 00:10:26,639", "arabic": "لَوْ كُنْتَ مَكَانَ أَخِيكَ، أَكُنْتَ تَفْعَلُ مَا فَعَلَ؟", "segs": null, "full_uz": "Aka o'rnida bo'lganingda, u qilgan ishni qilarmiding?", "note": null},
{"num": 92, "time": "00:10:28,639 --> 00:10:31,600", "arabic": "مَا كُلُّ سُؤَالٍ يُسْعِفُنِي جَوَابُهُ يَا أَبِي.", "segs": null, "full_uz": "Har bir savolning javobi menga qulay kelavermaydi, dadajon.", "note": null},
{"num": 100, "time": "00:14:08,639 --> 00:14:16,639", "arabic": "جَزَاكَ اللَّهُ خَيْرًا يَا أَمِيرَ الْمُؤْمِنِينَ عَلَى مَا أَمَرْتَ بِهِ مِنْ إِنْزَالِ الْإِمَامِ الشَّهِيدِ أَحْمَدَ بْنِ نَصْرٍ الْخُزَاعِيِّ.", "segs": [{"ar": "جَزَاكَ اللَّهُ خَيْرًا يَا", "uz": "Alloh sizga yaxshilik bersin,"}, {"ar": "أَمِيرَ الْمُؤْمِنِينَ عَلَى مَا أَمَرْتَ", "uz": "ey mo'minlar amiri,"}, {"ar": "بِهِ مِنْ إِنْزَالِ الْإِمَامِ الشَّهِيدِ أَحْمَدَ بْنِ نَصْرٍ الْخُزَاعِيِّ.", "uz": "shahid Imom Ahmad ibn Nasr al-Xuzoiyni pastga tushirish haqida buyruq berganingiz uchun."}], "full_uz": "Alloh sizga yaxshilik bersin, ey mo'minlar amiri, shahid Imom Ahmad ibn Nasr al-Xuzoiyni pastga tushirish haqida buyruq berganingiz uchun.", "note": null},
{"num": 102, "time": "00:14:16,639 --> 00:14:18,759", "arabic": "رَزَقَكَ اللَّهُ.", "segs": null, "full_uz": "Alloh senga rizq bersin.", "note": null},
{"num": 103, "time": "00:14:18,759 --> 00:14:26,759", "arabic": "كَمْ أَسْعَدْتَ قُلُوبًا كَثِيرَةً بِذَلِكَ، وَبِمَا فَعَلْتَهُ مِنْ قَبْلُ مِنْ مُحَارَبَةِ الْبِدَعِ وَالضَّلَالَةِ.", "segs": [{"ar": "كَمْ أَسْعَدْتَ قُلُوبًا كَثِيرَةً بِذَلِكَ،", "uz": "Buning bilan va ilgari bid'at va"}, {"ar": "وَبِمَا فَعَلْتَهُ مِنْ قَبْلُ مِنْ مُحَارَبَةِ الْبِدَعِ وَالضَّلَالَةِ.", "uz": "adashuvga qarshi kurashganingiz bilan ko'plab qalblarni qanchalik xursand qildingiz."}], "full_uz": "Buning bilan va ilgari bid'at va adashuvga qarshi kurashganingiz bilan ko'plab qalblarni qanchalik xursand qildingiz.", "note": null},
{"num": 105, "time": "00:14:26,759 --> 00:14:42,120", "arabic": "تَعْلَمُ أَنِّي أَرَدْتُ ذَلِكَ مُنْذُ أَنْ تَوَلَّيْتُ الْأَمْرَ يَا ابْنَ الْجَهْمِ، وَلَكِنَّ الْغَوْغَاءَ أَثَارُوا ضَجَّةً حِينَهَا، وَخَشِيتُ إِنْ أَنَا مَضَيْتُ فِي الْأَمْرِ أَنْ يُقْدِمَ عَلَى حَمَاقَةٍ تُؤَدِّي إِلَى سَفْكِ دِمَاءِ الْمُسْلِمِينَ.", "segs": [{"ar": "تَعْلَمُ أَنِّي أَرَدْتُ ذَلِكَ مُنْذُ أَنْ", "uz": "Bilasizki, men hokimiyatni qo'lga olganimdan beri buni xohlagan edim,"}, {"ar": "تَوَلَّيْتُ الْأَمْرَ يَا ابْنَ الْجَهْمِ،", "uz": "ey Ibn al-Jahm,"}, {"ar": "وَلَكِنَّ الْغَوْغَاءَ أَثَارُوا ضَجَّةً حِينَهَا،", "uz": "lekin o'shanda olomon shov-shuv ko'targan edi,"}, {"ar": "وَخَشِيتُ إِنْ أَنَا مَضَيْتُ فِي الْأَمْرِ أَنْ يُقْدِمَ", "uz": "va agar bu ishda davom etsam, biror nodonlikka yo'l qo'yib,"}, {"ar": "عَلَى حَمَاقَةٍ تُؤَدِّي إِلَى سَفْكِ دِمَاءِ الْمُسْلِمِينَ.", "uz": "musulmonlarning qonini to'kishga olib borishidan qo'rqqan edim."}], "full_uz": "Bilasizki, men hokimiyatni qo'lga olganimdan beri buni xohlagan edim, ey Ibn al-Jahm, lekin o'shanda olomon shov-shuv ko'targan edi, va agar bu ishda davom etsam, biror nodonlikka yo'l qo'yib, musulmonlarning qonini to'kishga olib borishidan qo'rqqan edim.", "note": null},
{"num": 109, "time": "00:14:42,120 --> 00:15:08,359", "arabic": "كَأَنَّنَا كُنَّا فِي بِئْرٍ سَحِيقَةٍ، وَجَاءَتِ الْبِشَارَةُ لِتُخْرِجَنَا مِنْهَا يَا مَوْلَايَ، وَمَا أَظْلَمَ مِنْ جُبِّ الْبِدَعِ وَالضَّلَالَةِ.", "segs": [{"ar": "كَأَنَّنَا كُنَّا فِي بِئْرٍ سَحِيقَةٍ،", "uz": "Go'yo biz chuqur bir quduqda edik,"}, {"ar": "وَجَاءَتِ الْبِشَارَةُ لِتُخْرِجَنَا مِنْهَا يَا مَوْلَايَ،", "uz": "va xushxabar bizni undan chiqarish uchun keldi,"}, {"ar": "وَمَا أَظْلَمَ مِنْ جُبِّ الْبِدَعِ وَالضَّلَالَةِ.", "uz": "xo'jayinim, bid'at va adashuv chohidan qorong'iroq narsa yo'q."}], "full_uz": "Go'yo biz chuqur bir quduqda edik, va xushxabar bizni undan chiqarish uchun keldi, xo'jayinim, bid'at va adashuv chohidan qorong'iroq narsa yo'q.", "note": null},
{"num": 112, "time": "00:15:08,359 --> 00:15:25,899", "arabic": "وَلَكِنِ الْحَمْدُ لِلَّهِ، فَقَدْ مَنَّ عَلَيْنَا بِكَ، فَأَحْيَيْتَ السُّنَّةَ وَأَمَتَّ الْبِدَعَ، وَوَضَعْتَ حَدًّا لِأَهْلِ الضَّلَالِ وَالْأَهْوَاءِ، بَعْدَ أَنْ صَالُوا وَجَالُوا فِي زَمَنِ أَمِيرِ الْمُؤْمِنِينَ الْوَاثِقِ رَحِمَهُ اللَّهُ.", "segs": [{"ar": "وَلَكِنِ الْحَمْدُ لِلَّهِ، فَقَدْ مَنَّ عَلَيْنَا بِكَ،", "uz": "Lekin, alhamdulillah, Alloh bizga siz orqali in'om qildi,"}, {"ar": "فَأَحْيَيْتَ السُّنَّةَ وَأَمَتَّ الْبِدَعَ،", "uz": "siz sunnatni tiriltirib, bid'atlarni o'ldirdingiz,"}, {"ar": "وَوَضَعْتَ حَدًّا لِأَهْلِ الضَّلَالِ وَالْأَهْوَاءِ،", "uz": "va adashuv va havo-nafs ahliga chegara qo'ydingiz,"}, {"ar": "بَعْدَ أَنْ صَالُوا وَجَالُوا فِي زَمَنِ أَمِيرِ الْمُؤْمِنِينَ الْوَاثِقِ رَحِمَهُ اللَّهُ.", "uz": "ular mo'minlar amiri Vosiq davrida erkin yurgandan keyin."}], "full_uz": "Lekin, alhamdulillah, Alloh bizga siz orqali in'om qildi, siz sunnatni tiriltirib, bid'atlarni o'ldirdingiz, va mo'minlar amiri Vosiq (Alloh unga rahmat qilsin) davrida erkin yurgan adashuv va havo-nafs ahliga chegara qo'ydingiz.", "note": null},
{"num": 117, "time": "00:15:25,899 --> 00:15:27,459", "arabic": "رَحِمَهُ اللَّهُ.", "segs": null, "full_uz": "Alloh unga rahmat qilsin.", "note": null},
{"num": 118, "time": "00:15:27,460 --> 00:15:40,840", "arabic": "رَحِمَ اللَّهُ أَخِي الْوَاثِقَ، وَتَقَبَّلَ تَوْبَتَهُ فِي آخِرِ أَيَّامِهِ.", "segs": null, "full_uz": "Alloh akam Vosiqqa rahmat qilsin, va uning oxirgi kunlaridagi tavbasini qabul qilsin.", "note": null},
{"num": 120, "time": "00:15:40,840 --> 00:15:47,000", "arabic": "يَا عَبْدَ اللَّهِ، نَاظِرِ ابْنَ أَبِي دُؤَادٍ.", "segs": null, "full_uz": "Ey Abdulloh, Ibn Abi Du'od bilan bahslash.", "note": null},
{"num": 121, "time": "00:15:47,000 --> 00:15:59,679", "arabic": "يَا أَمِيرَ الْمُؤْمِنِينَ، إِنَّهُ لَيْسَ أَهْلًا أَنْ يُنَاظِرَنِي وَلَا أَنْ أُنَاظِرَهُ، لَيْسَ أَهْلًا.", "segs": [{"ar": "يَا أَمِيرَ الْمُؤْمِنِينَ،", "uz": "Ey mo'minlar amiri,"}, {"ar": "إِنَّهُ لَيْسَ أَهْلًا أَنْ يُنَاظِرَنِي وَلَا أَنْ أُنَاظِرَهُ، لَيْسَ أَهْلًا.", "uz": "u men bilan bahslashishga ham, men u bilan bahslashishga ham loyiq emas, loyiq emas."}], "full_uz": "Ey mo'minlar amiri, u men bilan bahslashishga ham, men u bilan bahslashishga ham loyiq emas, loyiq emas.", "note": null},
{"num": 124, "time": "00:15:59,679 --> 00:16:11,139", "arabic": "أَهْوَنُ عَلَيْكَ يَا مَوْلَايَ، عِنْدَ الْمُنَاظَرَةِ يَظْهَرُ الْحَقُّ.", "segs": null, "full_uz": "Sizga yengil bo'lsin, xo'jayinim, bahs paytida haq oshkor bo'ladi.", "note": null},
{"num": 128, "time": "00:16:11,139 --> 00:16:22,379", "arabic": "إِنْ شِئْتَ يَا أَمِيرَ الْمُؤْمِنِينَ نَاظَرْتُ، مَا دَعَوْنَاكَ إِلَّا لِذَلِكَ.", "segs": [{"ar": "إِنْ شِئْتَ يَا أَمِيرَ الْمُؤْمِنِينَ نَاظَرْتُ،", "uz": "Xohlasangiz, mo'minlar amiri, bahslashaman,"}, {"ar": "مَا دَعَوْنَاكَ إِلَّا لِذَلِكَ.", "uz": "sizni faqat shuning uchun chaqirdik."}], "full_uz": "Xohlasangiz, mo'minlar amiri, bahslashaman, sizni faqat shuning uchun chaqirdik.", "note": null},
{"num": 131, "time": "00:16:22,379 --> 00:16:26,360", "arabic": "احْفَظْ عَلَيَّ وَعَلَيْهِ يَا مَوْلَايَ.", "segs": null, "full_uz": "Men va u haqimda [gaplarni] yodda tuting, xo'jayinim.", "note": null},
{"num": 132, "time": "00:16:26,360 --> 00:16:39,120", "arabic": "قُلْ لِي أَيُّهَا الْقَاضِي، مَا قَوْلُكَ فِي الْقُرْآنِ؟ الْقُرْآنُ مَخْلُوقٌ.", "segs": [{"ar": "قُلْ لِي أَيُّهَا الْقَاضِي،", "uz": "Ayting-chi, qozi,"}, {"ar": "مَا قَوْلُكَ فِي الْقُرْآنِ؟ الْقُرْآنُ مَخْلُوقٌ.", "uz": "Qur'on haqida fikringiz qanday? Qur'on yaratilgandir."}], "full_uz": "Ayting-chi, qozi, Qur'on haqida fikringiz qanday? Qur'on yaratilgandir.", "note": null},
{"num": 135, "time": "00:16:39,120 --> 00:17:19,579", "arabic": "أَخْبِرْنِي عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حِينَ بُعِثَ نَبِيًّا، هَلْ سَتَرَ شَيْئًا مِمَّا أُمِرَ بِهِ؟ لَا. هَلْ سَتَرَ مَقَالَتَكَ هَذِهِ أَمْ دَعَا النَّاسَ إِلَيْهَا؟ هَذِهِ وَاحِدَةٌ يَا أَمِيرَ الْمُؤْمِنِينَ.", "segs": [{"ar": "أَخْبِرْنِي عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، حِينَ بُعِثَ نَبِيًّا،", "uz": "Menga ayting: Rasululloh (sollallohu alayhi va sallam) payg'ambar qilib yuborilganida,"}, {"ar": "هَلْ سَتَرَ شَيْئًا مِمَّا أُمِرَ بِهِ؟ لَا.", "uz": "buyurilgan narsalardan biror narsani yashirdimi? Yo'q."}, {"ar": "هَلْ سَتَرَ مَقَالَتَكَ هَذِهِ أَمْ دَعَا النَّاسَ إِلَيْهَا؟", "uz": "U sizning bu gapingizni yashirgan bo'lardimi yoki odamlarni unga chaqirgan bo'larmidi?"}, {"ar": "هَذِهِ وَاحِدَةٌ يَا أَمِيرَ الْمُؤْمِنِينَ.", "uz": "Mana bu birinchisi, ey mo'minlar amiri."}], "full_uz": "Menga ayting: Rasululloh (sollallohu alayhi va sallam) payg'ambar qilib yuborilganida, buyurilgan narsalardan biror narsani yashirdimi? Yo'q. Uni sizning bu gapingizni yashirgan bo'lardimi yoki odamlarni unga chaqirgan bo'larmidi? Mana bu birinchisi, ey mo'minlar amiri.", "note": null},
{"num": 142, "time": "00:17:19,579 --> 00:17:52,180", "arabic": "ثُمَّ أَخْبِرْنِي عَنِ اللَّهِ سُبْحَانَهُ وَتَعَالَى حِينَ قَالَ: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ، هَلْ كَانَ سُبْحَانَهُ وَتَعَالَى هُوَ الصَّادِقَ فِي إِكْمَالِ دِينِهِ أَمْ أَنَّكَ أَنْتَ الصَّادِقُ بِنُقْصَانِهِ حَتَّى تُقَالَ مَقَالَتُكَ؟ هَذِهِ ثَانِيَةٌ يَا مَوْلَايَ.", "segs": [{"ar": "ثُمَّ أَخْبِرْنِي عَنِ اللَّهِ سُبْحَانَهُ وَتَعَالَى حِينَ قَالَ: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ،", "uz": "So'ngra menga ayting: Alloh pok va oliy Zot: \"Bugun sizlar uchun dinigizni mukammal qildim\" deganida,"}, {"ar": "هَلْ كَانَ سُبْحَانَهُ وَتَعَالَى هُوَ الصَّادِقَ فِي إِكْمَالِ دِينِهِ", "uz": "U pok va oliy Zot dinini mukammal qilishda sodiqmidi,"}, {"ar": "أَمْ أَنَّكَ أَنْتَ الصَّادِقُ بِنُقْصَانِهِ حَتَّى تُقَالَ مَقَالَتُكَ؟", "uz": "yoki siz uning nuqsonli ekanida sodiqmisiz, sizning gapingiz aytilishi uchun?"}, {"ar": "هَذِهِ ثَانِيَةٌ يَا مَوْلَايَ.", "uz": "Mana bu ikkinchisi, xo'jayinim."}], "full_uz": "So'ngra menga ayting: Alloh pok va oliy Zot: \"Bugun sizlar uchun dinigizni mukammal qildim\" deganida, U pok va oliy Zot dinini mukammal qilishda sodiqmidi, yoki siz uning nuqsonli ekanida sodiqmisiz, sizning gapingiz aytilishi uchun? Mana bu ikkinchisi, xo'jayinim.", "note": "Qur'on, Moida surasi, 3-oyat."},
{"num": 148, "time": "00:17:52,180 --> 00:17:52,960", "arabic": "نَعَمْ.", "segs": null, "full_uz": "Ha.", "note": null},
{"num": 149, "time": "00:17:52,960 --> 00:18:19,980", "arabic": "ثُمَّ أَخْبِرْنِي عَنْ مَقَالَتِكَ هَذِهِ، أَعَلِمَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْ جَهِلَهَا؟ أَعَلِمَهَا. هَلْ دَعَا النَّاسَ إِلَيْهَا؟ ثَلَاثٌ.", "segs": [{"ar": "ثُمَّ أَخْبِرْنِي عَنْ مَقَالَتِكَ هَذِهِ،", "uz": "So'ngra sizning bu gapingiz haqida"}, {"ar": "أَعَلِمَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ", "uz": "ayting: Rasululloh (sollallohu alayhi va sallam)"}, {"ar": "وَسَلَّمَ أَمْ جَهِلَهَا؟ أَعَلِمَهَا.", "uz": "uni bilarmidi yoki bilmasmidi?"}, {"ar": "هَلْ دَعَا النَّاسَ إِلَيْهَا؟ ثَلَاثٌ.", "uz": "Bilar edi. Odamlarni unga chaqirganmi? Uchinchisi."}], "full_uz": "So'ngra sizning bu gapingiz haqida ayting: Rasululloh (sollallohu alayhi va sallam) uni bilarmidi yoki bilmasmidi? Bilar edi. Odamlarni unga chaqirganmi? Uchinchisi.", "note": null},
{"num": 154, "time": "00:18:19,980 --> 00:18:29,180", "arabic": "لَا. قُلْتُ لَكَ يَا أَمِيرَ الْمُؤْمِنِينَ لَيْسَ أَهْلًا لِمُنَاظَرَتِي.", "segs": null, "full_uz": "Yo'q. Senga aytdim-ku, ey mo'minlar amiri, u men bilan bahslashishga loyiq emas.", "note": null},
{"num": 157, "time": "00:18:39,180 --> 00:18:41,200", "arabic": "اجْعَلْنِي فِي حِلٍّ يَا شَيْخُ.", "segs": null, "full_uz": "Meni halol qiling, shayx.", "note": null},
{"num": 158, "time": "00:18:41,200 --> 00:18:55,980", "arabic": "وَاللَّهِ يَا أَمِيرَ الْمُؤْمِنِينَ لَقَدْ جَعَلْتُكَ فِي حِلٍّ وَسَعَةٍ مِنْ أَوَّلِ يَوْمٍ، إِكْرَامًا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.", "segs": [{"ar": "وَاللَّهِ يَا أَمِيرَ الْمُؤْمِنِينَ لَقَدْ جَعَلْتُكَ فِي حِلٍّ", "uz": "Vallohi, ey mo'minlar amiri, sizni birinchi kunidanoq halol"}, {"ar": "وَسَعَةٍ مِنْ أَوَّلِ يَوْمٍ،", "uz": "va kechirilgan qilgan edim,"}, {"ar": "إِكْرَامًا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.", "uz": "Rasululloh (sollallohu alayhi va sallam)ni hurmat qilib."}], "full_uz": "Vallohi, ey mo'minlar amiri, sizni birinchi kunidanoq halol va kechirilgan qilgan edim, Rasululloh (sollallohu alayhi va sallam)ni hurmat qilib.", "note": null},
{"num": 162, "time": "00:18:55,980 --> 00:18:59,740", "arabic": "أَيُّهَا الْحَرَسُ، فُكُّوا قَيْدًا.", "segs": null, "full_uz": "Ey qorovullar, kishanni yeching.", "note": null},
{"num": 164, "time": "00:19:08,079 --> 00:19:15,640", "arabic": "وَلَمْ يَمْتَحِنْ أَخِي الْوَاثِقُ بَعْدَ ذَلِكَ أَحَدًا، وَسَقَطَتْ عِنْدَهُ مَكَانَةُ ابْنِ أَبِي دُؤَادٍ.", "segs": [{"ar": "وَلَمْ يَمْتَحِنْ أَخِي الْوَاثِقُ بَعْدَ ذَلِكَ أَحَدًا،", "uz": "Va akam Vosiq bundan keyin hech kimni sinovga solmadi,"}, {"ar": "وَسَقَطَتْ عِنْدَهُ مَكَانَةُ ابْنِ أَبِي دُؤَادٍ.", "uz": "va uning oldida Ibn Abi Du'odning mavqei qulab tushdi."}], "full_uz": "Va akam Vosiq bundan keyin hech kimni sinovga solmadi, va uning oldida Ibn Abi Du'odning mavqei qulab tushdi.", "note": null},
{"num": 166, "time": "00:19:15,640 --> 00:19:19,960", "arabic": "هَدَّاكَ اللَّهُ أَمِيرَ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Alloh sizni hidoyat qilsin, ey mo'minlar amiri.", "note": null},
{"num": 167, "time": "00:19:19,960 --> 00:19:27,519", "arabic": "أَنْتَ تَعْلَمُ أَنَّ التَّوْبَةَ تَجُبُّ مَا قَبْلَهَا، كَمَا أَنَّ الْإِسْلَامَ يَجُبُّ مَا قَبْلَهُ.", "segs": [{"ar": "أَنْتَ تَعْلَمُ أَنَّ التَّوْبَةَ تَجُبُّ مَا قَبْلَهَا،", "uz": "Bilasizki, tavba o'zidan avvalgisini yo'qqa chiqaradi,"}, {"ar": "كَمَا أَنَّ الْإِسْلَامَ يَجُبُّ مَا قَبْلَهُ.", "uz": "xuddi Islom ham o'zidan avvalgisini yo'qqa chiqargandek."}], "full_uz": "Bilasizki, tavba o'zidan avvalgisini yo'qqa chiqaradi, xuddi Islom ham o'zidan avvalgisini yo'qqa chiqargandek.", "note": "\"الإسلام يجب ما قبله\" — Sahih Muslimdagi hadisga ishora."},
{"num": 169, "time": "00:19:27,519 --> 00:19:42,400", "arabic": "وَإِنِّي لَأَرْجُو أَنْ يَغْفِرَ اللَّهُ لِأَمِيرِ الْمُؤْمِنِينَ الْوَاثِقِ بِتَوْبَتِهِ، وَبِمَا فَعَلَهُ مِنْ بِرٍّ وَإِكْرَامٍ لِأَهْلِ الْحَرَمَيْنِ، مَكَّةَ الْمُكَرَّمَةِ وَالْمَدِينَةِ الْمُنَوَّرَةِ.", "segs": [{"ar": "وَإِنِّي لَأَرْجُو أَنْ يَغْفِرَ", "uz": "Umid qilamanki,"}, {"ar": "اللَّهُ لِأَمِيرِ الْمُؤْمِنِينَ الْوَاثِقِ بِتَوْبَتِهِ،", "uz": "Alloh mo'minlar amiri Vosiqni uning tavbasi va Makka"}, {"ar": "وَبِمَا فَعَلَهُ مِنْ بِرٍّ وَإِكْرَامٍ لِأَهْلِ الْحَرَمَيْنِ،", "uz": "al-Mukarrama hamda Madina al-Munavvara ahliga qilgan yaxshiligi va"}, {"ar": "مَكَّةَ الْمُكَرَّمَةِ وَالْمَدِينَةِ الْمُنَوَّرَةِ.", "uz": "hurmati bilan mag'firat qiladi."}], "full_uz": "Umid qilamanki, Alloh mo'minlar amiri Vosiqni uning tavbasi va Makka al-Mukarrama hamda Madina al-Munavvara ahliga qilgan yaxshiligi va hurmati bilan mag'firat qiladi.", "note": null},
{"num": 172, "time": "00:19:42,400 --> 00:19:58,940", "arabic": "كَانَ الْوَاثِقُ رَحِمَهُ اللَّهُ بَارًّا بِأَهْلِ مَكَّةَ وَالْمَدِينَةِ.", "segs": null, "full_uz": "Vosiq (Alloh unga rahmat qilsin) Makka va Madina ahliga yaxshilik qiluvchi edi.", "note": null},
{"num": 173, "time": "00:19:58,940 --> 00:20:06,880", "arabic": "إِلَّا أَنَّهُ تَرَكَ عَلَى كَاهِلِي حِمْلًا ثَقِيلًا، لَا أَدْرِي كَيْفَ أَلْقَى اللَّهَ بِهِ يَا ابْنَ الْجَهْمِ.", "segs": [{"ar": "إِلَّا أَنَّهُ تَرَكَ عَلَى كَاهِلِي حِمْلًا ثَقِيلًا،", "uz": "Lekin u mening yelkamga og'ir bir yuk qoldirdi,"}, {"ar": "لَا أَدْرِي كَيْفَ أَلْقَى", "uz": "bu bilan Allohga qanday duch kelishimni bilmayman,"}, {"ar": "اللَّهَ بِهِ يَا ابْنَ الْجَهْمِ.", "uz": "ey Ibn al-Jahm."}], "full_uz": "Lekin u mening yelkamga og'ir bir yuk qoldirdi, bu bilan Allohga qanday duch kelishimni bilmayman, ey Ibn al-Jahm.", "note": null},
{"num": 175, "time": "00:20:06,880 --> 00:20:18,380", "arabic": "وَلَوْلَا ذَلِكَ لَمَا بَقِيَتْ جُثَّةُ الْإِمَامِ أَحْمَدَ بْنِ نَصْرٍ الْخُزَاعِيِّ تَتَوَسَّلُ الدَّفْنَ خَمْسَ سِنِينَ وَلَمْ تَجِدْ لَهَا سَبِيلًا.", "segs": [{"ar": "وَلَوْلَا ذَلِكَ لَمَا بَقِيَتْ جُثَّةُ الْإِمَامِ أَحْمَدَ", "uz": "Aks holda Imom Ahmad ibn Nasr al-Xuzoiyning jasadi"}, {"ar": "بْنِ نَصْرٍ الْخُزَاعِيِّ تَتَوَسَّلُ الدَّفْنَ خَمْسَ سِنِينَ", "uz": "besh yil davomida dafn etilishni iltimos qilib,"}, {"ar": "وَلَمْ تَجِدْ لَهَا سَبِيلًا.", "uz": "unga yo'l topa olmay qolmagan bo'lardi."}], "full_uz": "Aks holda Imom Ahmad ibn Nasr al-Xuzoiyning jasadi besh yil davomida dafn etilishni iltimos qilib, unga yo'l topa olmay qolmagan bo'lardi.", "note": null},
{"num": 177, "time": "00:20:18,380 --> 00:20:26,500", "arabic": "قَدْ بَذَلْتَ وُسْعَكَ يَا أَمِيرَ الْمُؤْمِنِينَ، يَكْفِيكَ أَنَّكَ حَارَبْتَ الْبِدَعَ وَنَشَرْتَ السُّنَّةَ.", "segs": [{"ar": "قَدْ بَذَلْتَ وُسْعَكَ يَا أَمِيرَ الْمُؤْمِنِينَ،", "uz": "Siz qo'lingizdan kelganini qildingiz, ey mo'minlar amiri,"}, {"ar": "يَكْفِيكَ أَنَّكَ حَارَبْتَ الْبِدَعَ وَنَشَرْتَ السُّنَّةَ.", "uz": "bid'atlarga qarshi kurashib, sunnatni tarqatganingiz sizga yetarli."}], "full_uz": "Siz qo'lingizdan kelganini qildingiz, ey mo'minlar amiri, bid'atlarga qarshi kurashib, sunnatni tarqatganingiz sizga yetarli.", "note": null},
{"num": 179, "time": "00:20:30,760 --> 00:20:33,360", "arabic": "بَقِيَ أَمْرٌ وَاحِدٌ يَا ابْنَ الْجَهْمِ.", "segs": null, "full_uz": "Bitta ish qoldi, ey Ibn al-Jahm.", "note": null},
{"num": 180, "time": "00:20:33,359 --> 00:20:37,579", "arabic": "مَا هُوَ أَعَزَّكَ اللَّهُ يَا أَمِيرَ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Nima ekan, Alloh sizni aziz qilsin, ey mo'minlar amiri?", "note": null},
{"num": 181, "time": "00:20:37,579 --> 00:20:40,819", "arabic": "أَحْمَدُ بْنُ حَنْبَلٍ.", "segs": null, "full_uz": "Ahmad ibn Hanbal.", "note": null},
{"num": 182, "time": "00:20:40,819 --> 00:20:49,399", "arabic": "أَهْلًا يَا إِمَامُ.", "segs": null, "full_uz": "Xush kelibsiz, Imom.", "note": null},
{"num": 183, "time": "00:20:49,399 --> 00:20:50,599", "arabic": "إِنَّهُ إِمَامُنَا.", "segs": null, "full_uz": "U bizning imomimiz.", "note": null},
{"num": 184, "time": "00:20:50,599 --> 00:20:55,419", "arabic": "أَهْلًا وَسَهْلًا يَا إِمَامُ، شَرَّفْتَنَا يَا إِمَامُ.", "segs": null, "full_uz": "Xush kelibsiz, Imom, bizni sharafladingiz, Imom.", "note": null},
{"num": 188, "time": "00:20:55,419 --> 00:20:58,399", "arabic": "بَارَكَ اللَّهُ فِيكُمْ.", "segs": null, "full_uz": "Alloh sizlarga barakot bersin.", "note": null},
{"num": 189, "time": "00:20:58,400 --> 00:21:10,600", "arabic": "أَخِيرًا أَنْتَ بَيْنَ مُحِبِّيكَ، كَمْ تَحْتَاجُكَ النَّاسُ يَا إِمَامُ، بَارَكَ اللَّهُ فِيكَ.", "segs": [{"ar": "أَخِيرًا أَنْتَ بَيْنَ مُحِبِّيكَ،", "uz": "Nihoyat,"}, {"ar": "كَمْ تَحْتَاجُكَ النَّاسُ يَا إِمَامُ، بَارَكَ اللَّهُ فِيكَ.", "uz": "siz sevganlaringiz orasidasiz. Odamlar sizga qanchalik muhtoj, Imom, Alloh sizga barakot bersin."}], "full_uz": "Nihoyat, siz sevganlaringiz orasidasiz. Odamlar sizga qanchalik muhtoj, Imom, Alloh sizga barakot bersin.", "note": null},
{"num": 192, "time": "00:21:10,600 --> 00:21:13,060", "arabic": "أَسْتَغْفِرُ اللَّهَ الْعَلِيَّ الْعَظِيمَ.", "segs": null, "full_uz": "Buyuk va Ulug' Allohdan mag'firat so'rayman.", "note": null},
{"num": 193, "time": "00:21:13,060 --> 00:21:15,519", "arabic": "أَهْلًا وَسَهْلًا يَا إِمَامُ، تَفَضَّلْ.", "segs": null, "full_uz": "Xush kelibsiz, Imom, marhamat.", "note": null},
{"num": 195, "time": "00:21:15,519 --> 00:21:19,400", "arabic": "أَسْأَلُ اللَّهَ أَنْ يَنْفَعَ بِكَ.", "segs": null, "full_uz": "Allohdan siz orqali foyda berishini so'rayman.", "note": null},
{"num": 196, "time": "00:21:28,400 --> 00:21:40,940", "arabic": "عَلَى رِسْلِكِ يَا أُمِّي.", "segs": null, "full_uz": "Shoshilmang, onajon.", "note": null},
{"num": 197, "time": "00:21:40,940 --> 00:21:45,120", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 199, "time": "00:21:45,120 --> 00:21:47,580", "arabic": "لِمَاذَا تَأَخَّرْتِ؟", "segs": null, "full_uz": "Nega kechikding?", "note": null},
{"num": 200, "time": "00:21:47,580 --> 00:21:51,960", "arabic": "مَرَرْتُ بِدَارِ أَخِي عُمَيْرٍ، وَكَانَتِ الْحَرْبُ مُسْتَعِرَةً بَيْنَهُ وَبَيْنَ زَوْجِهِ.", "segs": [{"ar": "مَرَرْتُ بِدَارِ أَخِي عُمَيْرٍ،", "uz": "Ukam Umayrning uyiga borib qoldim,"}, {"ar": "وَكَانَتِ الْحَرْبُ مُسْتَعِرَةً بَيْنَهُ وَبَيْنَ زَوْجِهِ.", "uz": "u va xotini orasida urush qizib turgan edi."}], "full_uz": "Ukam Umayrning uyiga borib qoldim, u va xotini orasida urush qizib turgan edi.", "note": null},
{"num": 202, "time": "00:21:51,960 --> 00:22:03,000", "arabic": "هَذِهِ عَادَةٌ وَرِثَهَا عَنْ أَبِي رَحِمَهُ اللَّهُ، مَا ذَهَبَ لَيْلٌ وَأَشْرَقَ نَهَارٌ إِلَّا وَكَانَ أَبِي مَعَ أُمِّي فِي شِجَارٍ رَحِمَهُمَا اللَّهُ.", "segs": [{"ar": "هَذِهِ عَادَةٌ وَرِثَهَا عَنْ أَبِي رَحِمَهُ اللَّهُ،", "uz": "Bu odat unga otamdan (Alloh unga rahmat qilsin) meros bo'lib qolgan,"}, {"ar": "مَا ذَهَبَ لَيْلٌ وَأَشْرَقَ نَهَارٌ إِلَّا", "uz": "tun o'tib, kun yorishmasdi,"}, {"ar": "وَكَانَ أَبِي مَعَ أُمِّي", "uz": "otam onam bilan janjallashmasa,"}, {"ar": "فِي شِجَارٍ رَحِمَهُمَا اللَّهُ.", "uz": "Alloh ikkalasiga ham rahmat qilsin."}], "full_uz": "Bu odat unga otamdan (Alloh unga rahmat qilsin) meros bo'lib qolgan, tun o'tib, kun yorishmasdi, otam onam bilan janjallashmasa, Alloh ikkalasiga ham rahmat qilsin.", "note": null},
{"num": 204, "time": "00:22:03,000 --> 00:22:13,919", "arabic": "رَحِمَ اللَّهُ عَمِّي عَامِرًا، لَمْ يَبْدَأْ يَوْمًا بِشِجَارٍ، وَلَكِنَّ عَمَّتِي سَلْمَةَ رَحِمَهَا اللَّهُ هِيَ مَنْ كَانَتْ تَخْتَلِقُ الشِّجَارَ مَعَهُ لِأَتْفَهِ الْأَسْبَابِ، رَحِمَهُمَا اللَّهُ وَغَفَرَ لَهُمَا.", "segs": [{"ar": "رَحِمَ اللَّهُ عَمِّي عَامِرًا،", "uz": "Alloh amakim Omirga rahmat qilsin,"}, {"ar": "لَمْ يَبْدَأْ يَوْمًا بِشِجَارٍ،", "uz": "u hech qachon janjalni birinchi boshlamagan,"}, {"ar": "وَلَكِنَّ عَمَّتِي سَلْمَةَ رَحِمَهَا اللَّهُ هِيَ", "uz": "aksincha xolam Salama (Alloh unga rahmat qilsin)"}, {"ar": "مَنْ كَانَتْ تَخْتَلِقُ الشِّجَارَ مَعَهُ لِأَتْفَهِ الْأَسْبَابِ،", "uz": "eng arzimas sabablar bilan u bilan janjal chiqarar edi,"}, {"ar": "رَحِمَهُمَا اللَّهُ وَغَفَرَ لَهُمَا.", "uz": "Alloh ikkalasiga ham rahmat va mag'firat qilsin."}], "full_uz": "Alloh amakim Omirga rahmat qilsin, u hech qachon janjalni birinchi boshlamagan, aksincha xolam Salama (Alloh unga rahmat qilsin) eng arzimas sabablar bilan u bilan janjal chiqarar edi, Alloh ikkalasiga ham rahmat va mag'firat qilsin.", "note": null},
{"num": 207, "time": "00:22:22,279 --> 00:22:28,259", "arabic": "مَا أَقَلُّ مَا يُجْزِئُ مِنَ الْقُرْآنِ فِي الصَّلَاةِ؟ إِنْ قَرَأَ الْفَاتِحَةَ وَحْدَهَا أَجْزَأَ.", "segs": [{"ar": "مَا أَقَلُّ مَا يُجْزِئُ مِنَ الْقُرْآنِ فِي الصَّلَاةِ؟ إِنْ قَرَأَ الْفَاتِحَةَ", "uz": "Namozda Qur'ondan eng kami qancha yetadi? Agar faqat Fotihani o'qisa,"}, {"ar": "وَحْدَهَا أَجْزَأَ.", "uz": "yetadi."}], "full_uz": "Namozda Qur'ondan eng kami qancha yetadi? Agar faqat Fotihani o'qisa, yetadi.", "note": null},
{"num": 209, "time": "00:22:28,259 --> 00:22:34,240", "arabic": "مَا حُكْمُ الرَّجُلِ الَّذِي يَضْحَكُ فِي الصَّلَاةِ؟ عَلَيْهِ أَنْ يُعِيدَ الصَّلَاةَ.", "segs": [{"ar": "مَا حُكْمُ الرَّجُلِ الَّذِي يَضْحَكُ فِي", "uz": "Namozda kuladigan odamning hukmi qanday?"}, {"ar": "الصَّلَاةِ؟ عَلَيْهِ أَنْ يُعِيدَ الصَّلَاةَ.", "uz": "U namozni qaytadan o'qishi kerak."}], "full_uz": "Namozda kuladigan odamning hukmi qanday? U namozni qaytadan o'qishi kerak.", "note": null},
{"num": 211, "time": "00:22:34,240 --> 00:22:50,920", "arabic": "مَا تَقُولُ يَا إِمَامُ فِي الْقُنُوتِ فِي صَلَاةِ الْفَجْرِ؟ إِنْ كَانَ الْإِمَامُ يَقْنُتُ مُسْتَنْصِرًا لِعَدُوٍّ حَضَرَهُ فَلَا بَأْسَ بِالْقُنُوتِ فِي الْفَجْرِ، وَأَمَّا غَيْرُ ذَلِكَ فَلَا يُقْنَتُ.", "segs": [{"ar": "مَا تَقُولُ يَا إِمَامُ", "uz": "Bomdod namozidagi qunut haqida nima deysiz,"}, {"ar": "فِي الْقُنُوتِ فِي صَلَاةِ", "uz": "Imom?"}, {"ar": "الْفَجْرِ؟ إِنْ كَانَ الْإِمَامُ يَقْنُتُ مُسْتَنْصِرًا لِعَدُوٍّ حَضَرَهُ", "uz": "Agar imom hozir bo'lgan dushmanga qarshi yordam so'rab qunut qilsa,"}, {"ar": "فَلَا بَأْسَ بِالْقُنُوتِ فِي الْفَجْرِ،", "uz": "bomdodda qunut qilishda hech ne bo'ladi,"}, {"ar": "وَأَمَّا غَيْرُ ذَلِكَ فَلَا يُقْنَتُ.", "uz": "aks holda esa qunut qilinmaydi."}], "full_uz": "Bomdod namozidagi qunut haqida nima deysiz, Imom? Agar imom hozir bo'lgan dushmanga qarshi yordam so'rab qunut qilsa, bomdodda qunut qilishda hech ne bo'ladi, aks holda esa qunut qilinmaydi.", "note": null},
{"num": 215, "time": "00:22:50,920 --> 00:23:04,819", "arabic": "وَمَا تَقُولُ فِي حَدِيثِ ابْنِ عُمَرَ: كُنَّا نَأْكُلُ وَنَحْنُ نَسْعَى عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَنَشْرَبُ وَنَحْنُ قِيَامٌ؟ لَا أَدْرِي.", "segs": [{"ar": "وَمَا تَقُولُ فِي حَدِيثِ ابْنِ عُمَرَ:", "uz": "Ibn Umarning hadisi haqida nima deysiz:"}, {"ar": "كُنَّا نَأْكُلُ وَنَحْنُ نَسْعَى عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،", "uz": "\"Rasululloh (sav) davrida yurib-ovqatlanardik,\""}, {"ar": "وَنَشْرَبُ وَنَحْنُ قِيَامٌ؟", "uz": "\"va tik turib ichardik\"?"}, {"ar": "لَا أَدْرِي.", "uz": "Bilmayman."}], "full_uz": "Ibn Umarning \"Rasululloh (sav) davrida yurib-ovqatlanardik va tik turib ichardik\" hadisi haqida nima deysiz? Bilmayman.", "note": "Sahih Muslimdagi hadisga ishora."},
{"num": 220, "time": "00:23:23,259 --> 00:23:46,480", "arabic": "عَبْدَ اللَّهِ، خُذْ، انْقُلِ الْأَحَادِيثَ الَّتِي فِيهَا مَعَ الْأَحَادِيثِ الَّتِي مَعَكَ. كَيْفَ أُرَتِّبُهَا؟ ضَعْهَا فِي الْآخِرِ.", "segs": [{"ar": "عَبْدَ اللَّهِ، خُذْ،", "uz": "Abdulloh, ol,"}, {"ar": "انْقُلِ الْأَحَادِيثَ الَّتِي فِيهَا مَعَ الْأَحَادِيثِ الَّتِي مَعَكَ.", "uz": "undagi hadislarni sendagi hadislar bilan birga ko'chir."}, {"ar": "كَيْفَ أُرَتِّبُهَا؟", "uz": "Qanday tartiblay?"}, {"ar": "ضَعْهَا فِي الْآخِرِ.", "uz": "Oxiriga qo'y."}], "full_uz": "Abdulloh, ol, undagi hadislarni sendagi hadislar bilan birga ko'chir. Qanday tartiblay? Oxiriga qo'y.", "note": null},
{"num": 226, "time": "00:23:46,480 --> 00:23:53,240", "arabic": "عَدَدُ الْأَحَادِيثِ فِي الْمُسْنَدِ يُقَارِبُ الْأَرْبَعِينَ أَلْفَ حَدِيثٍ.", "segs": null, "full_uz": "Musnaddagi hadislar soni qariyb qirq minggacha yetadi.", "note": null},
{"num": 227, "time": "00:23:53,240 --> 00:24:18,200", "arabic": "أَبِي، هَلْ أَدْخَلْتَ فِي الْمُسْنَدِ كُلَّ الْأَحَادِيثِ الَّتِي حَفِظْتَهَا عَنْ شُيُوخِكَ؟ الَّذِي حَفِظْتُهُ مِنْ أَحَادِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَهِيَ كَثِيرَةٌ، وَلَكِنِّي فِي هَذَا الْمُسْنَدِ انْتَقَيْتُ بَعْضًا مِمَّا حَفِظْتُ، مِمَّا أَرَاهُ صَالِحًا لِلِاحْتِجَاجِ بِهِ وَالْعَمَلِ بِمُقْتَضَاهُ.", "segs": [{"ar": "أَبِي،", "uz": "Dadajon,"}, {"ar": "هَلْ أَدْخَلْتَ فِي الْمُسْنَدِ كُلَّ الْأَحَادِيثِ الَّتِي حَفِظْتَهَا عَنْ شُيُوخِكَ؟ الَّذِي حَفِظْتُهُ مِنْ أَحَادِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ", "uz": "Musnadga shayxlaringizdan yodlagan barcha hadislarni kiritdingizmi? Rasululloh (sav)ning hadislaridan yodlaganim juda ko'p,"}, {"ar": "وَسَلَّمَ فَهِيَ كَثِيرَةٌ،", "uz": "lekin bu Musnadda yodlaganlarimdan"}, {"ar": "وَلَكِنِّي فِي هَذَا الْمُسْنَدِ انْتَقَيْتُ بَعْضًا مِمَّا حَفِظْتُ،", "uz": "dalil sifatida ishlatishga va unga amal"}, {"ar": "مِمَّا أَرَاهُ صَالِحًا لِلِاحْتِجَاجِ بِهِ وَالْعَمَلِ بِمُقْتَضَاهُ.", "uz": "qilishga loyiq deb bilganlarimni tanlab oldim."}], "full_uz": "Dadajon, Musnadga shayxlaringizdan yodlagan barcha hadislarni kiritdingizmi? Rasululloh (sav)ning hadislaridan yodlaganim juda ko'p, lekin bu Musnadda yodlaganlarimdan dalil sifatida ishlatishga va unga amal qilishga loyiq deb bilganlarimni tanlab oldim.", "note": null},
{"num": 232, "time": "00:24:18,200 --> 00:24:26,360", "arabic": "أَمَا تَعِبْتُمْ؟ إِنَّكُمْ لَمْ تَذُوقُوا طَعَامًا مُنْذُ الظَّهِيرَةِ.", "segs": null, "full_uz": "Charchamadinglarmi? Peshindan beri taom totmadinglar-ku.", "note": null},
{"num": 233, "time": "00:24:26,360 --> 00:24:32,920", "arabic": "أَمَّا أَنَا فَمِحْبَرَتِي أَحَبُّ إِلَيَّ مِنْ طَعَامِي.", "segs": null, "full_uz": "Men uchun esa siyohdonim taomimdan azizroq.", "note": null},
{"num": 234, "time": "00:24:32,920 --> 00:24:42,980", "arabic": "يَا أَبَا عَبْدِ اللَّهِ، قَدْ بَلَغْتَ مِنَ الْعِلْمِ مَبْلَغًا حَتَّى أَصْبَحْتَ إِمَامًا لِلْمُسْلِمِينَ، وَمَا زِلْتَ مُتَعَلِّقًا بِمِحْبَرَتِكَ.", "segs": [{"ar": "يَا أَبَا عَبْدِ اللَّهِ،", "uz": "Ey Abu Abdulloh,"}, {"ar": "قَدْ بَلَغْتَ مِنَ الْعِلْمِ مَبْلَغًا حَتَّى أَصْبَحْتَ إِمَامًا لِلْمُسْلِمِينَ،", "uz": "ilmda shu darajaga yetdingizki, musulmonlar imomiga aylandingiz,"}, {"ar": "وَمَا زِلْتَ مُتَعَلِّقًا بِمِحْبَرَتِكَ.", "uz": "va hali ham siyohdoningizga bog'lanib qolibsiz."}], "full_uz": "Ey Abu Abdulloh, ilmda shu darajaga yetdingizki, musulmonlar imomiga aylandingiz, va hali ham siyohdoningizga bog'lanib qolibsiz.", "note": null},
{"num": 236, "time": "00:24:42,980 --> 00:24:53,420", "arabic": "سَأَطْلُبُ بِهَا الْعِلْمَ إِلَى أَنْ أَدْخُلَ الْقَبْرَ، مَعَ الْمِحْبَرَةِ إِلَى الْمَقْبَرَةِ.", "segs": [{"ar": "سَأَطْلُبُ بِهَا الْعِلْمَ إِلَى أَنْ أَدْخُلَ الْقَبْرَ،", "uz": "Qabrga kirguncha u bilan ilm izlashda davom etaman,"}, {"ar": "مَعَ الْمِحْبَرَةِ إِلَى الْمَقْبَرَةِ.", "uz": "siyohdon bilan qabristongacha."}], "full_uz": "Qabrga kirguncha u bilan ilm izlashda davom etaman, siyohdon bilan qabristongacha.", "note": null},
{"num": 238, "time": "00:24:53,420 --> 00:24:58,059", "arabic": "أَمَّا طَعَامُكُمْ فَلَا حَاجَةَ لِي فِيهِ.", "segs": null, "full_uz": "Sizning taomingizga esa hojatim yo'q.", "note": null},
{"num": 239, "time": "00:24:58,059 --> 00:25:02,519", "arabic": "انْظُرِي، لَعَلَّ عَبْدَ اللَّهِ يَكُونَ قَدْ جَاعَ.", "segs": null, "full_uz": "Qarang, balki Abdulloh och qolgandir.", "note": null},
{"num": 240, "time": "00:25:02,519 --> 00:25:05,779", "arabic": "أَجَلْ وَاللَّهِ يَا خَالُ، أَكَادُ أَنْ أَمُوتَ جُوعًا.", "segs": null, "full_uz": "Ha, vallohi, tog'ajon, ochlikdan o'lay deb qoldim.", "note": null},
{"num": 241, "time": "00:25:05,779 --> 00:25:08,099", "arabic": "وَأَخِيرًا وَجَدْتُ مَنْ يَجْبُرُ خَاطِرِي.", "segs": null, "full_uz": "Nihoyat, ko'nglimni ko'taradigan birontasini topdim.", "note": null},
{"num": 242, "time": "00:25:08,099 --> 00:25:10,620", "arabic": "سَأُحْضِرُ لَكَ الطَّعَامَ مِنَ الْمِحْبَرَةِ.", "segs": null, "full_uz": "Senga taomni siyohdondan olib kelaman.", "note": null},
{"num": 243, "time": "00:25:10,619 --> 00:25:14,579", "arabic": "لَقَدْ أَذْهَبْتَ عَقْلِي يَا أَبَا عَبْدِ اللَّهِ.", "segs": null, "full_uz": "Aqlimni yo'qotib qo'ydingiz, ey Abu Abdulloh.", "note": null},
{"num": 244, "time": "00:25:14,579 --> 00:25:17,059", "arabic": "أَيْنَ أُخْتِي فَاطِمَةُ؟", "segs": null, "full_uz": "Singlim Fotima qayerda?", "note": null},
{"num": 245, "time": "00:25:17,059 --> 00:25:24,719", "arabic": "لَقَدْ نَامَتْ مُنْذُ حِينٍ، رَأَتْكُمْ مَشْغُولِينَ بِالْأَوْرَاقِ وَالْمَحَابِرِ، فَلَمْ يُعْجِبْهَا الْأَمْرُ، فَنَامَتْ غَاضِبَةً.", "segs": [{"ar": "لَقَدْ نَامَتْ مُنْذُ حِينٍ، رَأَتْكُمْ مَشْغُولِينَ بِالْأَوْرَاقِ وَالْمَحَابِرِ،", "uz": "Bir muddat oldin uxlab qoldi, sizlarni qog'ozlar va siyohdonlar bilan band ko'rib,"}, {"ar": "فَلَمْ يُعْجِبْهَا الْأَمْرُ، فَنَامَتْ غَاضِبَةً.", "uz": "bu ish unga yoqmadi, shuning uchun g'azablanib uxlab qoldi."}], "full_uz": "Bir muddat oldin uxlab qoldi, sizlarni qog'ozlar va siyohdonlar bilan band ko'rib, bu ish unga yoqmadi, shuning uchun g'azablanib uxlab qoldi.", "note": null},
{"num": 249, "time": "00:25:24,719 --> 00:25:31,179", "arabic": "تُرِيدُ شَيْئًا يَا أَبَا عَبْدِ اللَّهِ؟", "segs": null, "full_uz": "Biror narsa istaysizmi, ey Abu Abdulloh?", "note": null},
{"num": 250, "time": "00:25:31,179 --> 00:25:33,779", "arabic": "لَا، جَزَاكِ اللَّهُ خَيْرًا.", "segs": null, "full_uz": "Yo'q, Alloh senga yaxshilik bersin.", "note": null},
{"num": 251, "time": "00:25:33,779 --> 00:25:38,799", "arabic": "وَلَكِنِ اسْتَعْجِلِي عَلَى عَبْدِ اللَّهِ قَبْلَ أَنْ يَمُوتَ جُوعًا.", "segs": null, "full_uz": "Lekin Abdulloh ochlikdan o'lmasdan oldin shoshiling.", "note": null},
{"num": 253, "time": "00:25:38,799 --> 00:25:59,559", "arabic": "الْمُتَوَكِّلُ يُرِيدُ أَنْ يُكْرِمَ أَحْمَدَ بْنَ حَنْبَلٍ، وَيُعَوِّضَهُ عَمَّا لَاقَاهُ فِي عَهْدِ أَسْلَافِهِ الْمَأْمُونِ وَالْمُعْتَصِمِ وَالْوَاثِقِ رَحِمَهُمُ اللَّهُ.", "segs": [{"ar": "الْمُتَوَكِّلُ يُرِيدُ أَنْ يُكْرِمَ أَحْمَدَ بْنَ حَنْبَلٍ،", "uz": "Mutavakkil Ahmad ibn Hanbalni hurmatlab, uni ajdodlari Ma'mun,"}, {"ar": "وَيُعَوِّضَهُ عَمَّا لَاقَاهُ فِي عَهْدِ أَسْلَافِهِ الْمَأْمُونِ", "uz": "Mu'tasim va Vosiq (Alloh ularga rahmat qilsin) davrida"}, {"ar": "وَالْمُعْتَصِمِ وَالْوَاثِقِ رَحِمَهُمُ اللَّهُ.", "uz": "ko'rgan azoblari uchun evaziga mukofotlamoqchi."}], "full_uz": "Mutavakkil Ahmad ibn Hanbalni hurmatlab, uni ajdodlari Ma'mun, Mu'tasim va Vosiq (Alloh ularga rahmat qilsin) davrida ko'rgan azoblari uchun evaziga mukofotlamoqchi.", "note": null},
{"num": 256, "time": "00:25:59,559 --> 00:26:01,859", "arabic": "مَاذَا تَقُولُ؟", "segs": null, "full_uz": "Nima deysan?", "note": null},
{"num": 257, "time": "00:26:01,859 --> 00:26:03,960", "arabic": "هَذَا مَا سَمِعْتُ وَالْخَبَرُ مُؤَكَّدٌ.", "segs": null, "full_uz": "Men eshitgan gap shu, va xabar aniqlangan.", "note": null},
{"num": 258, "time": "00:26:03,960 --> 00:26:17,139", "arabic": "أَيُّ أَحْمَقَ هَذَا؟ أَبَلَغَتْ بِهِ السَّفَاهَةُ أَنْ يُكْرِمَ ابْنَ حَنْبَلٍ مُهِينًا بِذَلِكَ سِيرَةَ أَهْلِي جَمِيعًا؟", "segs": [{"ar": "أَيُّ أَحْمَقَ هَذَا؟ أَبَلَغَتْ", "uz": "Bu qanaqa ahmoq?"}, {"ar": "بِهِ السَّفَاهَةُ أَنْ يُكْرِمَ", "uz": "Nodonligi shu darajaga yetdimi, Ibn Hanbalni hurmatlab,"}, {"ar": "ابْنَ حَنْبَلٍ مُهِينًا بِذَلِكَ سِيرَةَ أَهْلِي جَمِيعًا؟", "uz": "shu bilan mening barcha oilamning siyratini xo'rlaydimi?"}], "full_uz": "Bu qanaqa ahmoq? Nodonligi shu darajaga yetdimi, Ibn Hanbalni hurmatlab, shu bilan mening barcha oilamning siyratini xo'rlaydimi?", "note": null},
{"num": 260, "time": "00:26:17,139 --> 00:26:27,619", "arabic": "يَبْدُو أَنَّهُ قَدْ أَسْكَرَهُ مَدِيحُ أَهْلِ الضَّلَالَةِ لَهُ، فَقَرَّرَ أَنْ يَزِلَّ بِقَدَمِهِ فِي تِلْكَ الْحُفَيْرَةِ.", "segs": [{"ar": "يَبْدُو أَنَّهُ قَدْ أَسْكَرَهُ", "uz": "Ko'rinishidan, adashuv ahlining unga bo'lgan"}, {"ar": "مَدِيحُ أَهْلِ الضَّلَالَةِ لَهُ،", "uz": "maqtovi uni mast qilib qo'ygan,"}, {"ar": "فَقَرَّرَ أَنْ يَزِلَّ بِقَدَمِهِ فِي تِلْكَ الْحُفَيْرَةِ.", "uz": "shuning uchun o'sha chuqurga oyog'i bilan qulashga qaror qilibdi."}], "full_uz": "Ko'rinishidan, adashuv ahlining unga bo'lgan maqtovi uni mast qilib qo'ygan, shuning uchun o'sha chuqurga oyog'i bilan qulashga qaror qilibdi.", "note": null},
{"num": 263, "time": "00:26:27,619 --> 00:26:31,519", "arabic": "إِنْ فَعَلَ ذَلِكَ فَقَدْ زَالَتْ بَيْنَنَا وَبَيْنَهُ الْأَسْبَابُ.", "segs": null, "full_uz": "Agar shunday qilsa, biz bilan uning orasidagi barcha aloqalar tugaydi.", "note": null},
{"num": 264, "time": "00:26:31,519 --> 00:26:40,900", "arabic": "لَا أَدْرِي إِلَى أَيْنَ يُرِيدُ أَنْ يَصِلَ الْمُتَوَكِّلُ هَذَا، أَنَسِيَ مَنْ أَوْصَلَهُ إِلَى ذَلِكَ الْكُرْسِيِّ؟ لَوْلَا هَؤُلَاءِ الرِّجَالُ لَكَانَ نِسْيًا مَنْسِيًّا.", "segs": [{"ar": "لَا أَدْرِي إِلَى أَيْنَ", "uz": "Bu Mutavakkil qayerga yetmoqchi ekanini bilmayman,"}, {"ar": "يُرِيدُ أَنْ يَصِلَ الْمُتَوَكِّلُ هَذَا،", "uz": "uni o'sha kursiga"}, {"ar": "أَنَسِيَ مَنْ أَوْصَلَهُ إِلَى ذَلِكَ الْكُرْسِيِّ؟", "uz": "olib chiqqan kishilarni unutdimi? Bu odamlar bo'lmaganida,"}, {"ar": "لَوْلَا هَؤُلَاءِ الرِّجَالُ لَكَانَ نِسْيًا مَنْسِيًّا.", "uz": "u butunlay unutilgan bo'lardi."}], "full_uz": "Bu Mutavakkil qayerga yetmoqchi ekanini bilmayman, uni o'sha kursiga olib chiqqan kishilarni unutdimi? Bu odamlar bo'lmaganida, u butunlay unutilgan bo'lardi.", "note": null},
{"num": 266, "time": "00:26:40,900 --> 00:26:49,160", "arabic": "لَوْ فَعَلَ ذَلِكَ، وَمَا أَظُنُّهُ إِلَّا فَاعِلًا لَا شَكَّ، فَقَدْ فَضَحَ أَمْرَنَا أَمَامَ النَّاسِ وَأَحْرَجَنَا.", "segs": [{"ar": "لَوْ فَعَلَ ذَلِكَ،", "uz": "Agar shunday qilsa —"}, {"ar": "وَمَا أَظُنُّهُ إِلَّا فَاعِلًا لَا شَكَّ،", "uz": "va shubhasiz shunday qiladi deb o'ylayman — u"}, {"ar": "فَقَدْ فَضَحَ أَمْرَنَا أَمَامَ النَّاسِ وَأَحْرَجَنَا.", "uz": "bizning ishimizni odamlar oldida oshkor qilib, bizni sharmanda qiladi."}], "full_uz": "Agar shunday qilsa — va shubhasiz shunday qiladi deb o'ylayman — u bizning ishimizni odamlar oldida oshkor qilib, bizni sharmanda qiladi.", "note": null},
{"num": 268, "time": "00:26:49,160 --> 00:26:51,280", "arabic": "اسْمَعْ يَا ابْنَ السِّرَاجِ.", "segs": null, "full_uz": "Eshit, Ibn Siroj.", "note": null},
{"num": 269, "time": "00:26:51,280 --> 00:27:08,359", "arabic": "أَنْتَ الْوَحِيدُ الَّذِي مَا زَالَ مِنْ بَيْنِ إِخْوَتِنَا يَسْتَطِيعُ أَنْ يَدْخُلَ عَلَى الرَّجُلِ فِي مَجْلِسِهِ، يَجِبُ أَنْ تَحُولَ دُونَ ذَلِكَ مَهْمَا كَلَّفَكَ الْأَمْرُ، أَفَهِمْتَ؟", "segs": [{"ar": "أَنْتَ الْوَحِيدُ الَّذِي مَا زَالَ مِنْ بَيْنِ إِخْوَتِنَا", "uz": "Birodarlarimiz orasida hali ham bu odamning majlisiga"}, {"ar": "يَسْتَطِيعُ أَنْ يَدْخُلَ عَلَى الرَّجُلِ فِي مَجْلِسِهِ،", "uz": "kira oladigan yagona kishi sensan,"}, {"ar": "يَجِبُ أَنْ تَحُولَ دُونَ ذَلِكَ مَهْمَا كَلَّفَكَ الْأَمْرُ،", "uz": "bunga qanday xarajat bo'lsa ham to'sqinlik qilishing kerak,"}, {"ar": "أَفَهِمْتَ؟", "uz": "tushundingmi?"}], "full_uz": "Birodarlarimiz orasida hali ham bu odamning majlisiga kira oladigan yagona kishi sensan, bunga qanday xarajat bo'lsa ham to'sqinlik qilishing kerak, tushundingmi?", "note": null},
{"num": 273, "time": "00:27:08,359 --> 00:27:19,640", "arabic": "أَنَا رَهْنُ إِشَارَتِكَ، وَلَكِنْ مَاذَا عَسَايَ أَنْ أَفْعَلَ؟ سَأُخْبِرُكَ مَاذَا تَفْعَلُ.", "segs": [{"ar": "أَنَا رَهْنُ إِشَارَتِكَ،", "uz": "Sizning ishorangizga bo'ysunaman,"}, {"ar": "وَلَكِنْ مَاذَا عَسَايَ أَنْ أَفْعَلَ؟ سَأُخْبِرُكَ مَاذَا تَفْعَلُ.", "uz": "lekin nima qilishim mumkin? Nima qilishingni senga aytaman."}], "full_uz": "Sizning ishorangizga bo'ysunaman, lekin nima qilishim mumkin? Nima qilishingni senga aytaman.", "note": null},
{"num": 275, "time": "00:27:19,640 --> 00:27:30,000", "arabic": "مَا قَوْلُكَ يَا إِمَامُ فِي حُكْمِ مَسِّ الْمُصْحَفِ لِغَيْرِ الطَّاهِرِ؟ لَا يَمَسُّ الْمُصْحَفَ إِلَّا طَاهِرٌ.", "segs": [{"ar": "مَا قَوْلُكَ يَا إِمَامُ", "uz": "Poklanmagan kishining Mushafga tegishi haqida fikringiz qanday,"}, {"ar": "فِي حُكْمِ مَسِّ الْمُصْحَفِ", "uz": "Imom?"}, {"ar": "لِغَيْرِ الطَّاهِرِ؟ لَا يَمَسُّ الْمُصْحَفَ إِلَّا طَاهِرٌ.", "uz": "Faqat pok kishigina Mushafga tegishi mumkin."}], "full_uz": "Poklanmagan kishining Mushafga tegishi haqida fikringiz qanday, Imom? Faqat pok kishigina Mushafga tegishi mumkin.", "note": null},
{"num": 277, "time": "00:27:30,000 --> 00:27:48,399", "arabic": "يَا إِمَامُ، كَثِيرًا مَا تُسْأَلُ فَتَقُولُ: لَا أَدْرِي، لَا أَدْرِي، مَا أَبْرَدَهَا عَلَى الْكَبِدِ! وَيْلٌ لِلَّذِي يَقُولُ لِمَا لَا يَعْلَمُ إِنِّي أَعْلَمُ.", "segs": [{"ar": "يَا إِمَامُ، كَثِيرًا مَا تُسْأَلُ فَتَقُولُ: لَا أَدْرِي، لَا أَدْرِي،", "uz": "Imom, sizdan ko'p so'ralganda: \"Bilmayman, bilmayman\" deysiz,"}, {"ar": "مَا أَبْرَدَهَا عَلَى الْكَبِدِ!", "uz": "bu jigarga naqadar salqin keladi!"}, {"ar": "وَيْلٌ لِلَّذِي يَقُولُ لِمَا لَا يَعْلَمُ إِنِّي أَعْلَمُ.", "uz": "Bilmagan narsasi haqida \"bilaman\" deyuvchiga voy bo'lsin."}], "full_uz": "Imom, sizdan ko'p so'ralganda: \"Bilmayman, bilmayman\" deysiz, bu jigarga naqadar salqin keladi! Bilmagan narsasi haqida \"bilaman\" deyuvchiga voy bo'lsin.", "note": null},
{"num": 284, "time": "00:27:48,399 --> 00:28:12,860", "arabic": "قَالَ عُقْبَةُ بْنُ مُسْلِمٍ: صَاحَبْتُ ابْنَ عُمَرَ، فَكَثِيرًا مَا كَانَ يُسْأَلُ فَيَقُولُ: لَا أَدْرِي، ثُمَّ الْتَفَتَ إِلَيَّ وَقَالَ: تَدْرِي مَا يُرِيدُ هَؤُلَاءِ؟ يُرِيدُونَ أَنْ يَجْعَلُوا ظُهُورَنَا جِسْرًا لَهُمْ إِلَى جَهَنَّمَ.", "segs": [{"ar": "قَالَ عُقْبَةُ بْنُ مُسْلِمٍ: صَاحَبْتُ ابْنَ عُمَرَ،", "uz": "Uqba ibn Muslim aytadi: \"Men Ibn Umarga hamroh bo'ldim,\""}, {"ar": "فَكَثِيرًا مَا كَانَ يُسْأَلُ فَيَقُولُ: لَا أَدْرِي،", "uz": "undan ko'p so'ralganida u: 'Bilmayman' der edi,\""}, {"ar": "ثُمَّ الْتَفَتَ إِلَيَّ وَقَالَ: تَدْرِي مَا يُرِيدُ هَؤُلَاءِ؟", "uz": "so'ng menga qarab: 'Bilasanmi bular nima istaydi?' dedi,"}, {"ar": "يُرِيدُونَ أَنْ يَجْعَلُوا ظُهُورَنَا جِسْرًا لَهُمْ إِلَى جَهَنَّمَ.", "uz": "'Ular orqamizni o'zlariga jahannamga ko'prik qilib olishni istashadi.'"}], "full_uz": "Uqba ibn Muslim aytadi: \"Men Ibn Umarga hamroh bo'ldim, undan ko'p so'ralganida u: 'Bilmayman' der edi, so'ng menga qarab: 'Bilasanmi bular nima istaydi? Ular orqamizni o'zlariga jahannamga ko'prik qilib olishni istashadi' dedi.\"", "note": "Ibn Umar (r.a.) haqidagi mashhur asar (rivoyat)."},
{"num": 292, "time": "00:28:32,920 --> 00:28:46,360", "arabic": "أَتَعْرِفُ يَا حُسْنُ؟ لَا أَحْمِلُ فِي عُنُقِي دَيْنًا لِأَحَدٍ كَمَا أَحْمِلُ لِأُمِّي رَحِمَهَا اللَّهُ.", "segs": [{"ar": "أَتَعْرِفُ يَا حُسْنُ؟ لَا أَحْمِلُ فِي عُنُقِي", "uz": "Bilasanmi, Husn? Onamga (Alloh unga rahmat qilsin) bo'lgan"}, {"ar": "دَيْنًا لِأَحَدٍ كَمَا أَحْمِلُ لِأُمِّي رَحِمَهَا اللَّهُ.", "uz": "qarzimni hech kimga bunday tarzda his qilmayman."}], "full_uz": "Bilasanmi, Husn? Onamga (Alloh unga rahmat qilsin) bo'lgan qarzimni hech kimga bunday tarzda his qilmayman.", "note": null},
{"num": 295, "time": "00:28:46,360 --> 00:28:54,400", "arabic": "كَمْ وَدِدْتُ لَوْ أَنَّ اللَّهَ مَدَّ فِي عُمْرِهَا حَتَّى أُوَفِّيَهَا حَقَّهَا.", "segs": [{"ar": "كَمْ", "uz": "Alloh uning umrini uzaytirib,"}, {"ar": "وَدِدْتُ لَوْ أَنَّ اللَّهَ مَدَّ فِي عُمْرِهَا حَتَّى أُوَفِّيَهَا حَقَّهَا.", "uz": "unga haqini to'liq to'lashimni qanchalik istardim."}], "full_uz": "Alloh uning umrini uzaytirib, unga haqini to'liq to'lashimni qanchalik istardim.", "note": null},
{"num": 297, "time": "00:28:54,400 --> 00:29:02,560", "arabic": "فَكَمْ كَانَتْ تُعَانِي مِنْ كَثْرَةِ قَرَاطِيسِي وَمَحَابِرِي، كَمَا تُعَانِينَ أَنْتِ الْآنَ.", "segs": [{"ar": "فَكَمْ كَانَتْ تُعَانِي مِنْ كَثْرَةِ قَرَاطِيسِي وَمَحَابِرِي،", "uz": "U ham mening qog'ozlarim va siyohdonlarimning ko'pligidan qanchalik aziyat chekkan edi,"}, {"ar": "كَمَا تُعَانِينَ أَنْتِ الْآنَ.", "uz": "xuddi sen hozir chekayotganingdek."}], "full_uz": "U ham mening qog'ozlarim va siyohdonlarimning ko'pligidan qanchalik aziyat chekkan edi, xuddi sen hozir chekayotganingdek.", "note": null},
{"num": 299, "time": "00:29:02,559 --> 00:29:08,220", "arabic": "رَحِمَكِ اللَّهُ يَا أُمِّي.", "segs": null, "full_uz": "Alloh senga rahmat qilsin, onajon.", "note": null},
{"num": 300, "time": "00:29:08,220 --> 00:29:28,419", "arabic": "هَذَا لَطِيبِكَ يَا مَوْلَايَ، وَلَوْلَا قُوَّةُ إِيمَانِكَ لَكَانَ مَا مَرَّ بِكَ مِنَ الْقَسْوَةِ لَمْ يَزِدْكَ إِلَّا رِقَّةَ الْقَلْبِ وَمَزِيدًا مِنَ الْحُبِّ لِلنَّاسِ، فَكُنْتَ خَيْرَ أَبٍ لِبَنِيكَ وَخَيْرَ رَجُلٍ لِنِسَائِكَ.", "segs": [{"ar": "هَذَا لَطِيبِكَ يَا مَوْلَايَ،", "uz": "Bu sizning poklikingizdan, xo'jayinim,"}, {"ar": "وَلَوْلَا قُوَّةُ إِيمَانِكَ لَكَانَ مَا مَرَّ بِكَ", "uz": "va imoningizning kuchi bo'lmaganida, boshingizdan o'tgan qattiqchiliklar sizga faqat qalb"}, {"ar": "مِنَ الْقَسْوَةِ لَمْ يَزِدْكَ إِلَّا رِقَّةَ الْقَلْبِ", "uz": "yumshoqligi va odamlarga bo'lgan muhabbatni ko'proq qo'shar edi,"}, {"ar": "وَمَزِيدًا مِنَ الْحُبِّ لِلنَّاسِ،", "uz": "shunday qilib siz farzandlaringiz uchun eng"}, {"ar": "فَكُنْتَ خَيْرَ أَبٍ لِبَنِيكَ وَخَيْرَ رَجُلٍ لِنِسَائِكَ.", "uz": "yaxshi ota va ayollaringiz uchun eng yaxshi er bo'ldingiz."}], "full_uz": "Bu sizning poklikingizdan, xo'jayinim, va imoningizning kuchi bo'lmaganida, boshingizdan o'tgan qattiqchiliklar sizga faqat qalb yumshoqligi va odamlarga bo'lgan muhabbatni ko'proq qo'shar edi, shunday qilib siz farzandlaringiz uchun eng yaxshi ota va ayollaringiz uchun eng yaxshi er bo'ldingiz.", "note": null},
{"num": 307, "time": "00:29:28,419 --> 00:29:30,240", "arabic": "يَا حُسْنُ.", "segs": null, "full_uz": "Ey Husn.", "note": null},
{"num": 308, "time": "00:29:30,240 --> 00:29:40,099", "arabic": "إِنَّمَا النِّسَاءُ شَقَائِقُ الرِّجَالِ، مَا أَكْرَمَهُنَّ إِلَّا كَرِيمٌ، وَمَا أَهَانَهُنَّ إِلَّا لَئِيمٌ.", "segs": [{"ar": "إِنَّمَا النِّسَاءُ شَقَائِقُ الرِّجَالِ،", "uz": "Ayollar erkaklarning tengdoshlaridir,"}, {"ar": "مَا أَكْرَمَهُنَّ إِلَّا كَرِيمٌ، وَمَا أَهَانَهُنَّ إِلَّا لَئِيمٌ.", "uz": "ularni faqat saxovatli kishi hurmat qiladi, va faqat past kishi haqoratlaydi."}], "full_uz": "Ayollar erkaklarning tengdoshlaridir, ularni faqat saxovatli kishi hurmat qiladi, va faqat past kishi haqoratlaydi.", "note": "\"النساء شقائق الرجال\" — Sunan Abu Dovud va Termiziydagi hadis."},
{"num": 311, "time": "00:29:40,099 --> 00:29:47,099", "arabic": "أَهَذَا مَا تَرَاهُ فِي الْمَرْأَةِ يَا مَوْلَايَ؟", "segs": null, "full_uz": "Ayolda ko'radigan narsangiz shumi, xo'jayinim?", "note": null},
{"num": 312, "time": "00:29:47,099 --> 00:29:59,880", "arabic": "بَلْ هَذَا مَا يَرَاهُ الْإِسْلَامُ يَا حُسْنُ، لَا يَبْخَسُ حَقَّ الْمَرْأَةِ إِلَّا جَاهِلٌ بِدِينِهِ.", "segs": [{"ar": "بَلْ هَذَا مَا يَرَاهُ الْإِسْلَامُ يَا حُسْنُ،", "uz": "Yo'q, bu Islom ko'rgan narsadir, ey Husn,"}, {"ar": "لَا يَبْخَسُ حَقَّ الْمَرْأَةِ إِلَّا جَاهِلٌ بِدِينِهِ.", "uz": "ayolning haqini faqat o'z diniga jaholat qiluvchi kamsitadi."}], "full_uz": "Yo'q, bu Islom ko'rgan narsadir, ey Husn, ayolning haqini faqat o'z diniga jaholat qiluvchi kamsitadi.", "note": null},
{"num": 315, "time": "00:30:00,240 --> 00:30:05,740", "arabic": "أَلَيْسَ فِي الْقُرْآنِ الْكَرِيمِ سُورَةٌ كَامِلَةٌ لِلنِّسَاءِ؟", "segs": null, "full_uz": "Qur'oni Karimda ayollar uchun butun bir sura yo'qmi?", "note": null},
{"num": 317, "time": "00:30:05,740 --> 00:30:18,539", "arabic": "أَلَمْ يَقُلْ سُبْحَانَهُ وَتَعَالَى: يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا؟", "segs": [{"ar": "أَلَمْ يَقُلْ سُبْحَانَهُ", "uz": "U pok va"}, {"ar": "وَتَعَالَى: يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ", "uz": "oliy Zot: \"Ey odamlar, sizlarni bitta jondan yaratgan va undan uning"}, {"ar": "وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا؟", "uz": "juftini yaratgan Robbingizdan qo'rqinglar\" demaganmidi?"}], "full_uz": "U pok va oliy Zot: \"Ey odamlar, sizlarni bitta jondan yaratgan va undan uning juftini yaratgan Robbingizdan qo'rqinglar\" demaganmidi?", "note": "Qur'on, Niso surasi, 1-oyat."},
{"num": 320, "time": "00:30:18,539 --> 00:30:25,420", "arabic": "أَلَمْ يَقُلْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اسْتَوْصُوا بِالنِّسَاءِ خَيْرًا؟", "segs": null, "full_uz": "U (sollallohu alayhi va sallam): \"Ayollarga yaxshilik bilan vasiyat qilinglar\" demaganmidi?", "note": "Sahih Buxoriy va Muslimdagi hadis."},
{"num": 322, "time": "00:30:25,420 --> 00:30:34,320", "arabic": "يَا حُسْنُ، لَمْ تَعْرِفِ الْإِنْسَانِيَّةُ مِنْ كَرَّمَ الْمَرْأَةَ كَالْإِسْلَامِ.", "segs": null, "full_uz": "Ey Husn, insoniyat ayolni Islom kabi hurmat qilgan biror narsani bilmaydi.", "note": null},
{"num": 324, "time": "00:30:57,140 --> 00:30:59,140", "arabic": "هُوَ الْفَالِجُ يَا مَوْلَايَ.", "segs": null, "full_uz": "Bu falaj kasalligi, xo'jayinim.", "note": null},
{"num": 325, "time": "00:30:59,140 --> 00:31:04,140", "arabic": "أَلَيْسَ لَهُ عِلَاجٌ؟ هَلْ سَيَبْقَى أَبِي هَكَذَا؟", "segs": null, "full_uz": "Uning davosi yo'qmi? Otam shunday qolaveradimi?", "note": null},
{"num": 327, "time": "00:31:04,140 --> 00:31:06,140", "arabic": "إِلَى أَنْ يَشَاءَ اللَّهُ.", "segs": null, "full_uz": "Alloh xohlaguncha.", "note": null},
{"num": 328, "time": "00:31:09,140 --> 00:31:12,140", "arabic": "لَوْ شَرَحْتِ الْأَمْرَ لِأَبِيكِ لَعَلَّهُ يُسَاعِدُكِ.", "segs": null, "full_uz": "Ishni otangizga tushuntirsangiz, balki sizga yordam berar.", "note": null},
{"num": 329, "time": "00:31:12,140 --> 00:31:19,140", "arabic": "وَمَا يَمْلِكُ أَبِي حَتَّى يُسَاعِدَنِي يَا امْرَأَةُ؟ عِنْدَهُ زَوْجٌ وَعِيَالٌ وَبِالْكَادِ يَكْفِيهِ قُوتُ يَوْمِهِ.", "segs": [{"ar": "وَمَا يَمْلِكُ أَبِي حَتَّى يُسَاعِدَنِي يَا امْرَأَةُ؟ عِنْدَهُ زَوْجٌ", "uz": "Otamning nimasi bor menga yordam berishi uchun, ey ayol? Uning xotini va bolalari bor,"}, {"ar": "وَعِيَالٌ وَبِالْكَادِ يَكْفِيهِ قُوتُ يَوْمِهِ.", "uz": "kunlik rizqi zo'rg'a yetadi."}], "full_uz": "Otamning nimasi bor menga yordam berishi uchun, ey ayol? Uning xotini va bolalari bor, kunlik rizqi zo'rg'a yetadi.", "note": null},
{"num": 331, "time": "00:31:19,140 --> 00:31:26,140", "arabic": "إِذَنْ مِنْ أَيْنَ سَتَأْتِي لِلرَّجُلِ بِدَوَائِهِ؟ يَكْفِينَا اللَّهُ إِنْ شَاءَ يَا أُمَّ زُهَيْرٍ، يَكْفِينَا اللَّهُ.", "segs": [{"ar": "إِذَنْ مِنْ أَيْنَ سَتَأْتِي لِلرَّجُلِ بِدَوَائِهِ؟", "uz": "Unda odamga davosini qayerdan topasan? Alloh bizga kifoya qiladi,"}, {"ar": "يَكْفِينَا اللَّهُ إِنْ شَاءَ يَا أُمَّ زُهَيْرٍ،", "uz": "inshaalloh, ey Zuhayrning onasi,"}, {"ar": "يَكْفِينَا اللَّهُ.", "uz": "Alloh bizga kifoya qiladi."}], "full_uz": "Unda odamga davosini qayerdan topasan? Alloh bizga kifoya qiladi, inshaalloh, ey Zuhayrning onasi, Alloh bizga kifoya qiladi.", "note": null},
{"num": 333, "time": "00:31:26,140 --> 00:31:27,780", "arabic": "لَا أَدْرِي مَا أَقُولُ لَكَ يَا صَالِحُ.", "segs": null, "full_uz": "Senga nima deyishni bilmayman, Solih.", "note": null},
{"num": 334, "time": "00:31:27,780 --> 00:31:34,640", "arabic": "عَمِّي أَحْمَدُ بْنُ حَنْبَلٍ إِمَامُ بَغْدَادَ كُلِّهَا، وَيَعْجِزُ عَنْ خَمْسِينَ دِرْهَمًا يُعْطِيكَهَا تَفُكُّ ضَائِقَتَنَا وَتُفِيدُنَا؟", "segs": [{"ar": "عَمِّي أَحْمَدُ بْنُ حَنْبَلٍ إِمَامُ بَغْدَادَ كُلِّهَا،", "uz": "Amakim Ahmad ibn Hanbal butun Bag'dodning imomi,"}, {"ar": "وَيَعْجِزُ عَنْ خَمْسِينَ دِرْهَمًا يُعْطِيكَهَا تَفُكُّ ضَائِقَتَنَا", "uz": "va u senga bizning tang holimizni yechadigan va bizga foyda beradigan ellik dirham bera"}, {"ar": "وَتُفِيدُنَا؟", "uz": "olmaydimi?"}], "full_uz": "Amakim Ahmad ibn Hanbal butun Bag'dodning imomi, va u senga bizning tang holimizni yechadigan va bizga foyda beradigan ellik dirham bera olmaydimi?", "note": null},
{"num": 336, "time": "00:31:34,640 --> 00:31:39,720", "arabic": "وَمَاذَا تُرِيدِينَ مِنْ إِمَامِ بَغْدَادَ كُلِّهَا؟ أَنْ يَضَعَ ضَرَائِبَ عَلَى النَّاسِ حَتَّى يَجْمَعَ لَكِ الْمَالَ؟", "segs": [{"ar": "وَمَاذَا تُرِيدِينَ مِنْ إِمَامِ", "uz": "Butun Bag'dod imomidan nima istaysan?"}, {"ar": "بَغْدَادَ كُلِّهَا؟ أَنْ يَضَعَ", "uz": "Senga"}, {"ar": "ضَرَائِبَ عَلَى النَّاسِ حَتَّى يَجْمَعَ لَكِ الْمَالَ؟", "uz": "pul yig'ish uchun odamlarga soliq solsinmi?"}], "full_uz": "Butun Bag'dod imomidan nima istaysan? Senga pul yig'ish uchun odamlarga soliq solsinmi?", "note": null},
{"num": 338, "time": "00:31:39,720 --> 00:31:43,060", "arabic": "يَجْمَعُ لِي؟ وَمَا شَأْنِي أَنَا؟ إِنَّمَا أَتَكَلَّمُ لِأَجْلِكَ.", "segs": null, "full_uz": "Menga yig'sinmi? Menga nima daxli bor? Men faqat sen uchun gapiryapman.", "note": null},
{"num": 340, "time": "00:31:43,060 --> 00:31:45,440", "arabic": "جَزَاكِ اللَّهُ خَيْرًا يَا أُمَّ زُهَيْرٍ.", "segs": null, "full_uz": "Alloh senga yaxshilik bersin, ey Zuhayrning onasi.", "note": null},
{"num": 341, "time": "00:31:45,440 --> 00:31:49,020", "arabic": "لَا حَاجَةَ بِي إِلَى شَفَقَتِكِ، أَنَا أَعْلَمُ كَيْفَ أُدَبِّرُ شُؤُونِي.", "segs": [{"ar": "لَا حَاجَةَ بِي إِلَى شَفَقَتِكِ،", "uz": "Sening rahm-shafqatingga hojatim yo'q,"}, {"ar": "أَنَا أَعْلَمُ كَيْفَ أُدَبِّرُ شُؤُونِي.", "uz": "o'z ishlarimni qanday boshqarishni o'zim bilaman."}], "full_uz": "Sening rahm-shafqatingga hojatim yo'q, o'z ishlarimni qanday boshqarishni o'zim bilaman.", "note": null},
{"num": 343, "time": "00:31:49,020 --> 00:31:53,339", "arabic": "فَاجْمَعِ الْخَمْسِينَ دِرْهَمًا إِذَنْ، بَدَلَ أَنْ تَجْهَدَ فِي شَيْءٍ آخَرَ.", "segs": [{"ar": "فَاجْمَعِ الْخَمْسِينَ دِرْهَمًا إِذَنْ،", "uz": "Unda ellik dirhamni yig',"}, {"ar": "بَدَلَ أَنْ تَجْهَدَ فِي شَيْءٍ آخَرَ.", "uz": "boshqa narsaga urinib o'tirgandan ko'ra."}], "full_uz": "Unda ellik dirhamni yig', boshqa narsaga urinib o'tirgandan ko'ra.", "note": null},
{"num": 345, "time": "00:31:53,339 --> 00:31:57,880", "arabic": "يَبْدُو أَنَّ شَهِيَّتَكِ الْيَوْمَ مَفْتُوحَةٌ لِلشِّجَارِ، سَأَتْرُكُ لَكِ الْبَيْتَ حَتَّى أُرِيحَ وَأَسْتَرِيحَ.", "segs": [{"ar": "يَبْدُو أَنَّ شَهِيَّتَكِ الْيَوْمَ مَفْتُوحَةٌ لِلشِّجَارِ،", "uz": "Ko'rinishidan, bugun ishtahang janjalga ochilib qolibdi,"}, {"ar": "سَأَتْرُكُ لَكِ الْبَيْتَ حَتَّى أُرِيحَ وَأَسْتَرِيحَ.", "uz": "tinchlanish uchun uyni senga tashlab ketaman."}], "full_uz": "Ko'rinishidan, bugun ishtahang janjalga ochilib qolibdi, tinchlanish uchun uyni senga tashlab ketaman.", "note": null},
{"num": 347, "time": "00:31:57,880 --> 00:32:09,779", "arabic": "وَإِنْ قُلْتُمْ فَاعْدِلُوا يَا صَالِحُ، وَلَا يَنْسِكَ غَضَبُكَ الْإِنْصَافَ.", "segs": null, "full_uz": "Gapirganingizda adolatli bo'linglar, Solih, va g'azabing seni insofdan unuttirmasin.", "note": "Qur'on, An'om surasi, 152-oyatiga ishora."},
{"num": 349, "time": "00:32:09,779 --> 00:32:11,779", "arabic": "فَزَوْجُكَ لَكَ مُحِبَّةٌ.", "segs": null, "full_uz": "Xotining seni sevadi.", "note": null},
{"num": 350, "time": "00:32:11,779 --> 00:32:17,079", "arabic": "أَعْرِفُ، يَكَادُ حُبُّهَا يَقْتُلُنِي، بَلْ قَتَلَنِي يَا خَالَةُ.", "segs": null, "full_uz": "Bilaman, uning muhabbati meni deyarli o'ldiryapti, aksincha, meni o'ldirdi, xolajon.", "note": null},
{"num": 353, "time": "00:32:17,079 --> 00:32:20,140", "arabic": "أَعْدِلُوا، هُوَ أَقْرَبُ لِلتَّقْوَى يَا صَالِحُ.", "segs": null, "full_uz": "Adolatli bo'linglar, bu taqvoga yaqinroqdir, Solih.", "note": "Qur'on, Moida surasi, 8-oyatiga ishora."},
{"num": 355, "time": "00:32:20,140 --> 00:32:22,740", "arabic": "كَانَ اللَّهُ فِي الْعَوْنِ يَا خَالَةُ.", "segs": null, "full_uz": "Alloh yordamda bo'lsin, xolajon.", "note": null},
{"num": 356, "time": "00:32:22,740 --> 00:32:35,180", "arabic": "إِنَّكَ لَنْ تَنَالَ السَّعَادَةَ فِي بَيْتِكَ يَا وَلَدِي إِلَّا بِعَشْرِ خِصَالٍ تَمْنَحُهَا لِزَوْجِكَ، فَاحْفَظْهَا عَنِّي.", "segs": [{"ar": "إِنَّكَ لَنْ تَنَالَ السَّعَادَةَ فِي بَيْتِكَ يَا", "uz": "Uyingda o'nta xislatni xotiningga bermaguningcha baxtga erisha olmaysan,"}, {"ar": "وَلَدِي إِلَّا بِعَشْرِ خِصَالٍ تَمْنَحُهَا لِزَوْجِكَ،", "uz": "o'g'lim,"}, {"ar": "فَاحْفَظْهَا عَنِّي.", "uz": "shularni mendan yodda tut."}], "full_uz": "Uyingda o'nta xislatni xotiningga bermaguningcha baxtga erisha olmaysan, o'g'lim, shularni mendan yodda tut.", "note": null},
{"num": 360, "time": "00:32:35,180 --> 00:32:37,940", "arabic": "وَأَحْرِصْ عَلَيْهَا، وَأَحَدِّثْ بِهَا إِنْ شِئْتَ.", "segs": null, "full_uz": "Ularga rioya qil, va xohlasang, boshqalarga ham hikoya qil.", "note": null},
{"num": 361, "time": "00:32:37,940 --> 00:32:39,980", "arabic": "أَسْمَعُكَ يَا أَبِي.", "segs": null, "full_uz": "Sizni tinglayapman, dadajon.", "note": null},
{"num": 362, "time": "00:32:39,980 --> 00:32:59,819", "arabic": "أَمَّا الْأُولَى وَالثَّانِيَةُ فَإِنَّ النِّسَاءَ يُحْبِبْنَ الدَّلَالَ وَيُحْبِبْنَ التَّصْرِيحَ بِالْحُبِّ، فَلَا تَبْخَلْ عَلَى زَوْجِكَ بِذَلِكَ، فَإِنْ بَخِلْتَ جَعَلْتَ بَيْنَكَ وَبَيْنَهَا حِجَابًا مِنَ الْجَفْوَةِ وَنَقْصًا فِي الْمَوَدَّةِ.", "segs": [{"ar": "أَمَّا الْأُولَى وَالثَّانِيَةُ فَإِنَّ النِّسَاءَ يُحْبِبْنَ الدَّلَالَ وَيُحْبِبْنَ التَّصْرِيحَ بِالْحُبِّ،", "uz": "Birinchi va ikkinchisi: ayollar erkalanishni va muhabbatni ochiq izhor qilishni sevadilar,"}, {"ar": "فَلَا تَبْخَلْ عَلَى زَوْجِكَ بِذَلِكَ،", "uz": "buni xotiningdan ayamagin,"}, {"ar": "فَإِنْ بَخِلْتَ جَعَلْتَ بَيْنَكَ وَبَيْنَهَا حِجَابًا مِنَ الْجَفْوَةِ وَنَقْصًا فِي الْمَوَدَّةِ.", "uz": "agar ayasang, o'zing bilan uning orasiga sovuqlik pardasi va mehr-muhabbatda kamchilik qo'ygan bo'lasan."}], "full_uz": "Birinchi va ikkinchisi: ayollar erkalanishni va muhabbatni ochiq izhor qilishni sevadilar, buni xotiningdan ayamagin, agar ayasang, o'zing bilan uning orasiga sovuqlik pardasi va mehr-muhabbatda kamchilik qo'ygan bo'lasan.", "note": null},
{"num": 367, "time": "00:32:59,819 --> 00:33:03,180", "arabic": "لَعَمْرُ اللَّهِ إِنَّ ذَلِكَ الْحَقُّ لَا مِرَاءَ فِيهِ.", "segs": null, "full_uz": "Vallohi, bu haq gap, unda shubha yo'q.", "note": null},
{"num": 368, "time": "00:33:03,180 --> 00:33:22,000", "arabic": "أَمَّا الثَّالِثَةُ فَإِنَّ النِّسَاءَ يَكْرَهْنَ الرَّجُلَ الشَّدِيدَ الْحَازِمَ، وَيَسْتَخِفِفْنَ بِالرَّجُلِ الضَّعِيفِ اللَّيِّنِ، فَاجْعَلْ لِكُلِّ صِفَةٍ مَكَانَهَا، فَهَذَا أَدْعَى لِلْحُبِّ وَأَجْلَبُ لِلطُّمَأْنِينَةِ.", "segs": [{"ar": "أَمَّا الثَّالِثَةُ فَإِنَّ النِّسَاءَ يَكْرَهْنَ الرَّجُلَ الشَّدِيدَ الْحَازِمَ،", "uz": "Uchinchisi: ayollar juda qattiqqo'l erkakni yomon ko'radilar, va juda yumshoq,"}, {"ar": "وَيَسْتَخِفِفْنَ بِالرَّجُلِ الضَّعِيفِ اللَّيِّنِ،", "uz": "zaif erkakni past ko'radilar,"}, {"ar": "فَاجْعَلْ لِكُلِّ صِفَةٍ مَكَانَهَا،", "uz": "har bir xususiyatga o'z o'rnini ber,"}, {"ar": "فَهَذَا أَدْعَى لِلْحُبِّ وَأَجْلَبُ لِلطُّمَأْنِينَةِ.", "uz": "bu muhabbatga va xotirjamlikka yaqinroqdir."}], "full_uz": "Uchinchisi: ayollar juda qattiqqo'l erkakni yomon ko'radilar, va juda yumshoq, zaif erkakni past ko'radilar, har bir xususiyatga o'z o'rnini ber, bu muhabbatga va xotirjamlikka yaqinroqdir.", "note": null},
{"num": 372, "time": "00:33:22,000 --> 00:33:40,960", "arabic": "وَالرَّابِعَةُ يَا أَبِي؟ إِنَّ النِّسَاءَ يُحْبِبْنَ مِنَ الزَّوْجِ مَا يُحِبُّ الزَّوْجُ مِنْهُنَّ، مِنْ طِيبِ الْكَلَامِ وَحُسْنِ الْمَنْظَرِ وَنَظَافَةِ الثِّيَابِ وَطِيبِ الرَّائِحَةِ، فَكُنْ فِي كُلِّ أَحْوَالِكَ كَذَلِكَ.", "segs": [{"ar": "وَالرَّابِعَةُ يَا أَبِي؟ إِنَّ النِّسَاءَ يُحْبِبْنَ", "uz": "To'rtinchisi-chi, dadajon? Ayollar erdan xuddi er"}, {"ar": "مِنَ الزَّوْجِ مَا يُحِبُّ الزَّوْجُ مِنْهُنَّ،", "uz": "ulardan sevgan narsani sevadi — yoqimli so'z,"}, {"ar": "مِنْ طِيبِ الْكَلَامِ وَحُسْنِ الْمَنْظَرِ", "uz": "chiroyli ko'rinish,"}, {"ar": "وَنَظَافَةِ الثِّيَابِ وَطِيبِ الرَّائِحَةِ،", "uz": "kiyimning tozaligi va yoqimli hid,"}, {"ar": "فَكُنْ فِي كُلِّ أَحْوَالِكَ كَذَلِكَ.", "uz": "shuning uchun har doim shunday bo'l."}], "full_uz": "To'rtinchisi-chi, dadajon? Ayollar erdan xuddi er ulardan sevgan narsani sevadi — yoqimli so'z, chiroyli ko'rinish, kiyimning tozaligi va yoqimli hid, shuning uchun har doim shunday bo'l.", "note": null},
{"num": 376, "time": "00:33:40,960 --> 00:34:05,539", "arabic": "وَالْخَامِسَةُ؟ أَمَّا الْخَامِسَةُ فَإِنَّ الْبَيْتَ هُوَ مَمْلَكَةُ الْأُنْثَى، وَفِيهِ تَشْعُرُ بِأَنَّهَا مُتَرَبِّعَةٌ عَلَى عَرْشِهَا وَأَنَّهَا سَيِّدَةٌ فِيهِ، فَإِيَّاكَ أَنْ تَهْدِمَ هَذِهِ الْمَمْلَكَةَ الَّتِي تَعِيشُهَا، وَإِيَّاكَ أَنْ تُزِيحَهَا عَنْ عَرْشِهَا هَذَا.", "segs": [{"ar": "وَالْخَامِسَةُ؟ أَمَّا الْخَامِسَةُ فَإِنَّ الْبَيْتَ هُوَ مَمْلَكَةُ الْأُنْثَى،", "uz": "Beshinchisi-chi? Beshinchisi: uy — ayolning saltanatidir,"}, {"ar": "وَفِيهِ تَشْعُرُ بِأَنَّهَا مُتَرَبِّعَةٌ عَلَى عَرْشِهَا وَأَنَّهَا سَيِّدَةٌ فِيهِ،", "uz": "unda u o'z taxtida o'tirganini va uning bekasi ekanini his qiladi,"}, {"ar": "فَإِيَّاكَ أَنْ تَهْدِمَ هَذِهِ الْمَمْلَكَةَ الَّتِي تَعِيشُهَا،", "uz": "shu bois yashayotgan bu saltanatini vayron qilmagin,"}, {"ar": "وَإِيَّاكَ أَنْ تُزِيحَهَا عَنْ عَرْشِهَا هَذَا.", "uz": "va uni bu taxtidan surib tashlamagin."}], "full_uz": "Beshinchisi-chi? Beshinchisi: uy — ayolning saltanatidir, unda u o'z taxtida o'tirganini va uning bekasi ekanini his qiladi, shu bois yashayotgan bu saltanatini vayron qilmagin, va uni bu taxtidan surib tashlamagin.", "note": null},
{"num": 381, "time": "00:34:05,539 --> 00:34:10,099", "arabic": "فَإِنَّكَ إِنْ فَعَلْتَ نَازَعْتَهَا مُلْكَهَا.", "segs": null, "full_uz": "Chunki shunday qilsang, uning mulkiga tajovuz qilgan bo'lasan.", "note": null},
{"num": 382, "time": "00:34:10,099 --> 00:34:13,760", "arabic": "أَيْنَ أُمُّ زُهَيْرٍ لِتَسْمَعَ ذَلِكَ؟", "segs": null, "full_uz": "Buni eshitishi uchun Zuhayrning onasi qayerda?", "note": null},
{"num": 383, "time": "00:34:14,199 --> 00:34:36,179", "arabic": "أَمَّا السَّادِسَةُ فَإِنَّ الْمَرْأَةَ تُحِبُّ أَنْ تُكْسِبَ زَوْجَهَا وَلَا تَخْسَرَ أَهْلَهَا، فَإِيَّاكَ أَنْ تَجْعَلَ نَفْسَكَ مَعَ أَهْلِهَا فِي مِيزَانٍ وَاحِدٍ، فَإِمَّا أَنْتَ وَإِمَّا أَهْلُهَا، فَهِيَ وَإِنِ اخْتَارَتْكَ عَلَى أَهْلِهَا سَتَبْقَى فِي كَمَدٍ.", "segs": [{"ar": "أَمَّا السَّادِسَةُ فَإِنَّ الْمَرْأَةَ تُحِبُّ أَنْ تُكْسِبَ زَوْجَهَا وَلَا تَخْسَرَ أَهْلَهَا،", "uz": "Oltinchisi: ayol erini qozonib, oilasini yo'qotmaslikni istaydi,"}, {"ar": "فَإِيَّاكَ أَنْ تَجْعَلَ نَفْسَكَ مَعَ أَهْلِهَا فِي مِيزَانٍ وَاحِدٍ،", "uz": "shuning uchun o'zingni uning oilasi bilan bir tarozida qo'ymagin,"}, {"ar": "فَإِمَّا أَنْتَ وَإِمَّا أَهْلُهَا،", "uz": "yo sen, yo uning oilasi,"}, {"ar": "فَهِيَ وَإِنِ اخْتَارَتْكَ عَلَى أَهْلِهَا سَتَبْقَى فِي كَمَدٍ.", "uz": "agar u seni oilasidan afzal ko'rsa ham, qayg'uda qolaveradi."}], "full_uz": "Oltinchisi: ayol erini qozonib, oilasini yo'qotmaslikni istaydi, shuning uchun o'zingni uning oilasi bilan bir tarozida qo'ymagin, yo sen, yo uning oilasi — agar u seni oilasidan afzal ko'rsa ham, qayg'uda qolaveradi.", "note": null},
{"num": 386, "time": "00:34:36,179 --> 00:34:41,879", "arabic": "لَا بَأْسَ عَلَيْكَ يَا قَاضِيَ الْقُضَاةِ.", "segs": null, "full_uz": "Sizga hech gap yo'q, ey qozilar qozisi.", "note": null},
{"num": 387, "time": "00:34:41,879 --> 00:34:45,039", "arabic": "تَهَوُّرًا، إِنْ شَاءَ اللَّهُ خَيْرًا.", "segs": null, "full_uz": "Beparvolik, inshaalloh, hammasi yaxshilikka bo'lsin.", "note": null},
{"num": 388, "time": "00:34:45,039 --> 00:34:47,960", "arabic": "بِأَبِي أَنْتَ وَأُمِّي أَيُّهَا الْإِمَامُ.", "segs": null, "full_uz": "Otam-onam senga fido bo'lsin, ey Imom.", "note": null},
{"num": 389, "time": "00:34:47,960 --> 00:34:54,519", "arabic": "لَوْ تَعْلَمُوا خَوْفَنَا عَلَيْكَ وَهَلَعَنَا لِمَا أَصَابَكَ، لَقَدْ رَمَانَا الْخَبَرُ فِي قُلُوبِنَا.", "segs": [{"ar": "لَوْ تَعْلَمُوا خَوْفَنَا عَلَيْكَ وَهَلَعَنَا لِمَا أَصَابَكَ،", "uz": "Sizga bo'lgan xavotirimizni va sizga yetgan narsadan qo'rquvimizni bilsangiz edi,"}, {"ar": "لَقَدْ رَمَانَا الْخَبَرُ فِي قُلُوبِنَا.", "uz": "bu xabar qalblarimizga urildi."}], "full_uz": "Sizga bo'lgan xavotirimizni va sizga yetgan narsadan qo'rquvimizni bilsangiz edi, bu xabar qalblarimizga urildi.", "note": null},
{"num": 391, "time": "00:35:06,179 --> 00:35:10,559", "arabic": "مَاذَا تَقُولُ يَا سَيِّدِي؟", "segs": null, "full_uz": "Nima deyapsiz, xo'jayinim?", "note": null},
{"num": 392, "time": "00:35:10,559 --> 00:35:13,679", "arabic": "لَعَلَّهُ يَطْلُبُ شَيْئًا.", "segs": null, "full_uz": "Balki biror narsa so'raydi.", "note": null},
{"num": 393, "time": "00:35:13,679 --> 00:35:23,199", "arabic": "الْمُؤْمِنُ مُبْتَلًى يَا مَوْلَايَ.", "segs": null, "full_uz": "Mo'min sinaladi, xo'jayinim.", "note": null},
{"num": 394, "time": "00:35:36,179 --> 00:36:01,179", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 396, "time": "00:36:01,179 --> 00:36:09,540", "arabic": "مَوْلَانَا الْوَالِي يَتُوقُ لِحُضُورِكَ إِلَيْهِ، وَلَا يَمَلُّ مِنْ طَلَبِكَ.", "segs": null, "full_uz": "Xo'jayinimiz voliy sizning huzuriga kelishingizni intiqlik bilan kutmoqda, va sizni chaqirishdan charchamaydi.", "note": null},
{"num": 398, "time": "00:36:09,540 --> 00:36:13,760", "arabic": "وَمَاذَا يُرِيدُ مِنِّي؟", "segs": null, "full_uz": "Mendan nima istaydi?", "note": null},
{"num": 399, "time": "00:36:13,760 --> 00:36:15,340", "arabic": "مَا عَلَى الرَّسُولِ إِلَّا الْبَلَاغُ.", "segs": null, "full_uz": "Elchining vazifasi faqat yetkazishdir.", "note": "Qur'onda bir necha marta takrorlanadigan \"ما على الرسول إلا البلاغ\" iborasiga ishora (masalan, Nur surasi, 54-oyat)."},
{"num": 400, "time": "00:36:15,340 --> 00:36:16,760", "arabic": "هَيَّا.", "segs": null, "full_uz": "Yuring.", "note": null},
{"num": 401, "time": "00:36:16,760 --> 00:36:28,960", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 403, "time": "00:36:28,960 --> 00:36:30,680", "arabic": "مَاذَا يُرِيدُونَ؟", "segs": null, "full_uz": "Ular nima istashadi?", "note": null},
{"num": 404, "time": "00:36:32,060 --> 00:36:33,760", "arabic": "الْوَالِي يَطْلُبُ أَنْ أَزُورَهُ.", "segs": null, "full_uz": "Voliy meni ziyorat qilishimni so'ramoqda.", "note": null},
{"num": 405, "time": "00:36:33,760 --> 00:36:37,520", "arabic": "وَمَا شَأْنُ الْوَالِي عِنْدَكَ يَا أَبِي؟", "segs": null, "full_uz": "Voliyning sizga qanday ishi bor, dadajon?", "note": null},
{"num": 406, "time": "00:36:37,520 --> 00:36:39,840", "arabic": "إِنْ كُنْتَ تَعْلَمُ يَا وَلَدِي فَأَخْبِرْنِي.", "segs": null, "full_uz": "Agar bilsang, o'g'lim, menga aytib ber.", "note": null},
{"num": 407, "time": "00:36:39,840 --> 00:36:46,940", "arabic": "عَسَى أَنْ يَكُونَ خَيْرًا، اللَّهُمَّ سَلِّمْ، إِنْ شَاءَ اللَّهُ.", "segs": null, "full_uz": "Umid qilamanki, bu yaxshilikdir, ey Alloh, omon qil, inshaalloh.", "note": null},
{"num": 410, "time": "00:36:46,940 --> 00:36:49,320", "arabic": "تَجَهَّزْ لِتَخْرُجَ مَعِي.", "segs": null, "full_uz": "Men bilan chiqishga tayyorlan.", "note": null},
{"num": 411, "time": "00:36:49,320 --> 00:36:50,720", "arabic": "أَنَا جَاهِزٌ يَا أَبِي.", "segs": null, "full_uz": "Men tayyorman, dadajon.", "note": null},
{"num": 412, "time": "00:36:50,720 --> 00:36:54,320", "arabic": "أَغْلِقِ الْبَابَ.", "segs": null, "full_uz": "Eshikni yop.", "note": null},
{"num": 413, "time": "00:36:59,440 --> 00:37:00,920", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 414, "time": "00:37:00,920 --> 00:37:03,720", "arabic": "وَعَلَيْكُمُ السَّلَامُ.", "segs": null, "full_uz": "Va alaykum assalom.", "note": null},
{"num": 415, "time": "00:37:03,720 --> 00:37:29,659", "arabic": "الْحَقُّ يَا مَوْلَايَ أَنَّ لَدَيَّ أَخْبَارًا أَكِيدَةً أَنَّهُ ثَمَّ رَجُلٌ فِي بَغْدَادَ مُتَوَاطِئٌ مَعَ الطَّالِبِيِّينَ، وَقَدْ آوَى سَيِّدًا كَبِيرًا مِنْهُمْ، وَهُوَ يَدْعُو النَّاسَ إِلَى مُبَايَعَتِهِ سِرًّا.", "segs": [{"ar": "الْحَقُّ يَا مَوْلَايَ أَنَّ لَدَيَّ أَخْبَارًا أَكِيدَةً أَنَّهُ ثَمَّ رَجُلٌ فِي بَغْدَادَ مُتَوَاطِئٌ مَعَ الطَّالِبِيِّينَ،", "uz": "Rostini aytsam, xo'jayinim, menda Bag'dodda Tolibiylar bilan til biriktirgan bir odam borligi haqida aniq xabar bor,"}, {"ar": "وَقَدْ آوَى سَيِّدًا كَبِيرًا مِنْهُمْ،", "uz": "u ulardan katta bir sayyidni boshpanaga olgan,"}, {"ar": "وَهُوَ يَدْعُو النَّاسَ إِلَى مُبَايَعَتِهِ سِرًّا.", "uz": "va odamlarni maxfiy ravishda unga bay'at qilishga chaqirmoqda."}], "full_uz": "Rostini aytsam, xo'jayinim, menda Bag'dodda Tolibiylar bilan til biriktirgan bir odam borligi haqida aniq xabar bor, u ulardan katta bir sayyidni boshpanaga olgan, va odamlarni maxfiy ravishda unga bay'at qilishga chaqirmoqda.", "note": null},
{"num": 419, "time": "00:37:29,659 --> 00:37:34,480", "arabic": "مَاذَا؟ وَكَيْفَ غَابَ ذَلِكَ عَنْ أَنْظَارِ عُيُونِنَا؟", "segs": null, "full_uz": "Nima? Bu qanday qilib ko'zchilarimizning nazaridan chetda qoldi?", "note": null},
{"num": 420, "time": "00:37:34,480 --> 00:37:37,759", "arabic": "لِأَنَّهُ رَجُلٌ رَفَعَ ثَوْبَهُ عَنِ الشُّبُهَاتِ كَمَا يُقَالُ يَا مَوْلَايَ.", "segs": [{"ar": "لِأَنَّهُ رَجُلٌ رَفَعَ ثَوْبَهُ عَنِ", "uz": "Chunki u aytilishicha shubhalardan chetda turgan odam,"}, {"ar": "الشُّبُهَاتِ كَمَا يُقَالُ يَا مَوْلَايَ.", "uz": "xo'jayinim."}], "full_uz": "Chunki u aytilishicha shubhalardan chetda turgan odam, xo'jayinim.", "note": null},
{"num": 421, "time": "00:37:37,759 --> 00:37:43,319", "arabic": "مَنْ هُوَ؟", "segs": null, "full_uz": "U kim?", "note": null},
{"num": 422, "time": "00:37:43,319 --> 00:37:44,619", "arabic": "إِنَّهُ أَحْمَدُ بْنُ حَنْبَلٍ.", "segs": null, "full_uz": "U Ahmad ibn Hanbaldir.", "note": null},
{"num": 423, "time": "00:37:44,619 --> 00:37:56,299", "arabic": "يَا اللَّهُ.", "segs": null, "full_uz": "Yo Alloh.", "note": null},
{"num": 424, "time": "00:37:59,659 --> 00:38:26,879", "arabic": "أَهْلًا بِكَ يَا أَبَا عَبْدِ اللَّهِ، حَلَلْتَ أَهْلًا وَوَطِئْتَ سَهْلًا، تَبَارَكَ الْمَكَانُ بِوُجُودِكَ، تَفَضَّلْ يَا أَبَا عَبْدِ اللَّهِ.", "segs": [{"ar": "أَهْلًا بِكَ يَا أَبَا عَبْدِ اللَّهِ،", "uz": "Xush kelibsiz, ey Abu Abdulloh, siz o'z ahlingizga kelib,"}, {"ar": "حَلَلْتَ أَهْلًا وَوَطِئْتَ سَهْلًا،", "uz": "silliq yerga qadam qo'ydingiz,"}, {"ar": "تَبَارَكَ الْمَكَانُ بِوُجُودِكَ، تَفَضَّلْ يَا أَبَا عَبْدِ اللَّهِ.", "uz": "sizning huzuringiz bilan bu joy barakotli bo'ldi, marhamat, ey Abu Abdulloh."}], "full_uz": "Xush kelibsiz, ey Abu Abdulloh, siz o'z ahlingizga kelib, silliq yerga qadam qo'ydingiz, sizning huzuringiz bilan bu joy barakotli bo'ldi, marhamat, ey Abu Abdulloh.", "note": null},
{"num": 429, "time": "00:38:29,659 --> 00:38:42,920", "arabic": "تَفَضَّلْ يَا أَبَا عَبْدِ اللَّهِ اجْلِسْ، بَارَكَ اللَّهُ فِيكَ.", "segs": null, "full_uz": "Marhamat, ey Abu Abdulloh, o'tiring, Alloh sizga barakot bersin.", "note": null},
{"num": 432, "time": "00:38:42,920 --> 00:38:45,759", "arabic": "يَلَّا.", "segs": null, "full_uz": "Mayli.", "note": null},
{"num": 433, "time": "00:38:45,759 --> 00:38:57,819", "arabic": "أَعَزَّكَ اللَّهُ يَا أَبَا عَبْدِ اللَّهِ.", "segs": null, "full_uz": "Alloh sizni aziz qilsin, ey Abu Abdulloh.", "note": null},
{"num": 434, "time": "00:38:57,820 --> 00:39:08,480", "arabic": "إِنَّ أَمِيرَ الْمُؤْمِنِينَ طَلَبَ مِنِّي إِحْضَارَكَ إِلَيْهِ.", "segs": null, "full_uz": "Mo'minlar amiri mendan sizni o'z huzuriga olib kelishimni so'radi.", "note": null},
{"num": 435, "time": "00:39:08,480 --> 00:39:23,680", "arabic": "مَا لِي وَلِأَمِيرِ الْمُؤْمِنِينَ حَتَّى يُرْسِلَ فِي طَلَبِي؟ وَأَنَا كَمَا تَرَى مُتْعَبٌ وَمَرِيضٌ.", "segs": [{"ar": "مَا لِي وَلِأَمِيرِ الْمُؤْمِنِينَ حَتَّى يُرْسِلَ فِي طَلَبِي؟", "uz": "Mo'minlar amiri bilan mening qanday ishim borki, meni chaqirtiryapti?"}, {"ar": "وَأَنَا كَمَا تَرَى مُتْعَبٌ وَمَرِيضٌ.", "uz": "Ko'rib turganingizdek, men charchagan va kasalman."}], "full_uz": "Mo'minlar amiri bilan mening qanday ishim borki, meni chaqirtiryapti? Ko'rib turganingizdek, men charchagan va kasalman.", "note": null},
{"num": 437, "time": "00:39:23,679 --> 00:39:31,339", "arabic": "لَا بُدَّ مِنْ ذَلِكَ يَا إِمَامُ.", "segs": null, "full_uz": "Bu shart, Imom.", "note": null},
{"num": 439, "time": "00:39:31,339 --> 00:39:36,139", "arabic": "خَيْرًا إِنْ شَاءَ اللَّهُ.", "segs": null, "full_uz": "Yaxshilikka bo'lsin, inshaalloh.", "note": null},
{"num": 440, "time": "00:39:36,139 --> 00:39:41,019", "arabic": "السَّمْعُ وَالطَّاعَةُ لِأَمِيرِ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Mo'minlar amiriga eshitish va bo'ysunish.", "note": null},
{"num": 441, "time": "00:39:41,019 --> 00:39:50,980", "arabic": "وَثَمَّتْ حَاجَةٌ أُخْرَى. هِيَ لِي. تَفَضَّلْ أَعَزَّكَ اللَّهُ.", "segs": null, "full_uz": "Yana bir ehtiyoj bor. Bu meniki. Marhamat, Alloh sizni aziz qilsin.", "note": null},
{"num": 444, "time": "00:39:50,980 --> 00:40:07,820", "arabic": "أُرِيدُكَ أَنْ تَجْعَلَنِي فِي حِلٍّ مِنْ حُضُورِ طَرَبِكَ.", "segs": null, "full_uz": "Sendan bayramingga qatnashmaganim uchun meni halol qilishingni istayman.", "note": null},
{"num": 446, "time": "00:40:07,820 --> 00:40:15,639", "arabic": "غَفَرَ اللَّهُ لِي وَلَكَ.", "segs": null, "full_uz": "Alloh menga va senga mag'firat qilsin.", "note": null},
{"num": 447, "time": "00:40:15,639 --> 00:40:31,359", "arabic": "لَقَدْ جَعَلْتُ كُلَّ مَنْ حَضَرَ فِي حِلٍّ مِنْ أَمْرِي يَا ابْنَ مُصْعَبٍ، مُنْذُ أَنْ خَرَجْتُ مِنْ عِنْدِ أَمِيرِ الْمُؤْمِنِينَ الْمُعْتَصِمِ رَحِمَهُ اللَّهُ.", "segs": [{"ar": "لَقَدْ جَعَلْتُ كُلَّ مَنْ حَضَرَ فِي", "uz": "Mo'minlar amiri Mu'tasim (Alloh unga rahmat"}, {"ar": "حِلٍّ مِنْ أَمْرِي يَا ابْنَ مُصْعَبٍ،", "uz": "qilsin) huzuridan chiqqanimdan beri,"}, {"ar": "مُنْذُ أَنْ خَرَجْتُ مِنْ عِنْدِ", "uz": "hozir bo'lgan har bir kishini o'z ishimdan halol qilib qo'yganman,"}, {"ar": "أَمِيرِ الْمُؤْمِنِينَ الْمُعْتَصِمِ رَحِمَهُ اللَّهُ.", "uz": "ey Ibn Mus'ab."}], "full_uz": "Mo'minlar amiri Mu'tasim (Alloh unga rahmat qilsin) huzuridan chiqqanimdan beri, hozir bo'lgan har bir kishini o'z ishimdan halol qilib qo'yganman, ey Ibn Mus'ab.", "note": null},
{"num": 450, "time": "00:40:31,359 --> 00:40:39,259", "arabic": "يَا رَبِّ.", "segs": null, "full_uz": "Ey Robbim.", "note": null},
{"num": 451, "time": "00:40:39,260 --> 00:41:09,360", "arabic": "اللَّهُمَّ احْفَظْ عَبْدَكَ أَحْمَدَ بْنَ حَنْبَلٍ بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ، وَأَبْعِدْ عَنْهُ شَرَّ الْأَعْدَاءِ وَكَيْدَ الْحَاقِدِينَ، اللَّهُمَّ أَنْتَ تَعْلَمُ أَنْ لَيْسَ لَنَا بَعْدَكَ سِوَاهُ، فَاحْفَظْهُ بِحِفْظِكَ، وَكَلَأْهُ بِعَيْنِ رِعَايَتِكَ، وَجَنِّبْهُ مَا يَكْرَهُ وَنَكْرَهُ يَا رَبَّ الْعَالَمِينَ، آمِينَ.", "segs": [{"ar": "اللَّهُمَّ احْفَظْ عَبْدَكَ أَحْمَدَ بْنَ حَنْبَلٍ بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ،", "uz": "Ey Alloh, bandang Ahmad ibn Hanbalni solih bandalaringni asraganingdek asra,"}, {"ar": "وَأَبْعِدْ عَنْهُ شَرَّ الْأَعْدَاءِ وَكَيْدَ الْحَاقِدِينَ،", "uz": "undan dushmanlarning yomonligi va hasadgo'ylarning hiylasini uzoqlashtir,"}, {"ar": "اللَّهُمَّ أَنْتَ تَعْلَمُ أَنْ لَيْسَ لَنَا بَعْدَكَ سِوَاهُ، فَاحْفَظْهُ بِحِفْظِكَ، وَكَلَأْهُ بِعَيْنِ رِعَايَتِكَ،", "uz": "ey Alloh, bilasanki, Sendan boshqa bizga undan o'zga yo'q, uni O'z himoyang bilan asra, nazorating ko'zi bilan qo'riqla,"}, {"ar": "وَجَنِّبْهُ مَا يَكْرَهُ وَنَكْرَهُ يَا رَبَّ الْعَالَمِينَ، آمِينَ.", "uz": "va uni yomon ko'rgan narsadan chetlashtir, ey olamlarning Robbisi, omin."}], "full_uz": "Ey Alloh, bandang Ahmad ibn Hanbalni solih bandalaringni asraganingdek asra, undan dushmanlarning yomonligi va hasadgo'ylarning hiylasini uzoqlashtir. Ey Alloh, Sen bilasanki, Sendan boshqa bizga undan o'zga hech kim yo'q, uni O'z himoyang bilan asra, uni O'z nazoratingning ko'zi bilan qo'riqla, va uni o'zi va biz yomon ko'radigan narsadan chetlashtir, ey olamlarning Robbisi, omin.", "note": null},
{"num": 459, "time": "00:41:09,360 --> 00:41:13,019", "arabic": "يَا رَبِّ.", "segs": null, "full_uz": "Ey Robbim.", "note": null},
{"num": 461, "time": "00:41:13,019 --> 00:41:22,699", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 463, "time": "00:41:22,699 --> 00:41:28,059", "arabic": "جَاءَ أَبِي أَحْمَدُ بْنُ حَنْبَلٍ إِلَى دَارِ الْوِلَايَةِ مُنْذُ زَمَنٍ، وَوَدِدْتُ أَنْ أَطْمَئِنَّ عَلَيْهِ.", "segs": [{"ar": "جَاءَ أَبِي أَحْمَدُ بْنُ حَنْبَلٍ إِلَى دَارِ الْوِلَايَةِ مُنْذُ زَمَنٍ،", "uz": "Otam Ahmad ibn Hanbal ancha oldin voliylik uyiga borgan edi,"}, {"ar": "وَوَدِدْتُ أَنْ أَطْمَئِنَّ عَلَيْهِ.", "uz": "undan xabar olishni istadim."}], "full_uz": "Otam Ahmad ibn Hanbal ancha oldin voliylik uyiga borgan edi, undan xabar olishni istadim.", "note": null},
{"num": 465, "time": "00:41:28,059 --> 00:41:32,159", "arabic": "اطْمَئِنَّ، لَقَدْ ذَهَبَ مَعَ الْوَالِي إِلَى قَصْرِ أَمِيرِ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Xotirjam bo'ling, u voliy bilan birga mo'minlar amirining saroyiga ketdi.", "note": null},
{"num": 466, "time": "00:41:32,159 --> 00:41:55,019", "arabic": "حَسِبْتُ أَنَّنِي سَأَتَلَاعَبُ بِكَ كَيْفَمَا شِئْتُ يَا جَعْفَرُ، وَلَكِنْ يَبْدُو أَنَّكَ كُنْتَ أَذْكَى مِمَّا ظَنَنْتُ، وَطَرَحْتَ كُلَّ حِسَابَاتِي أَرْضًا، وَسَبَّبْتَ لِي مَا أَكْرَهُ.", "segs": [{"ar": "حَسِبْتُ أَنَّنِي سَأَتَلَاعَبُ بِكَ كَيْفَمَا شِئْتُ يَا جَعْفَرُ،", "uz": "Men xohlagancha seni o'ynatib qo'yaman deb o'ylagan edim, ey Ja'far,"}, {"ar": "وَلَكِنْ يَبْدُو أَنَّكَ كُنْتَ أَذْكَى مِمَّا ظَنَنْتُ،", "uz": "lekin ko'rinishidan, sen o'ylaganimdan aqlliroq ekansan,"}, {"ar": "وَطَرَحْتَ كُلَّ حِسَابَاتِي أَرْضًا، وَسَبَّبْتَ لِي مَا أَكْرَهُ.", "uz": "barcha hisob-kitoblarimni yerga urding, va menga yoqmaydigan narsaga sabab bo'lding."}], "full_uz": "Men xohlagancha seni o'ynatib qo'yaman deb o'ylagan edim, ey Ja'far, lekin ko'rinishidan, sen o'ylaganimdan aqlliroq ekansan, barcha hisob-kitoblarimni yerga urding, va menga yoqmaydigan narsaga sabab bo'lding.", "note": null},
{"num": 470, "time": "00:41:55,019 --> 00:42:03,900", "arabic": "لَمْ تَنْتَهِ الْمَعْرَكَةُ بَعْدُ يَا جَعْفَرُ، مَا دَامَ فِي الْجِسْمِ رَمَقٌ.", "segs": [{"ar": "لَمْ تَنْتَهِ الْمَعْرَكَةُ بَعْدُ يَا جَعْفَرُ،", "uz": "Jang hali tugagani yo'q, Ja'far,"}, {"ar": "مَا دَامَ فِي الْجِسْمِ رَمَقٌ.", "uz": "tanda jon bor ekan."}], "full_uz": "Jang hali tugagani yo'q, Ja'far, tanda jon bor ekan.", "note": null},
{"num": 472, "time": "00:42:03,900 --> 00:42:12,260", "arabic": "وَمَا مَصْلَحَةُ ابْنِ حَنْبَلٍ فِي فِعْلِ ذَلِكَ يَا أَبَا الْحَسَنِ؟", "segs": [{"ar": "وَمَا مَصْلَحَةُ ابْنِ حَنْبَلٍ فِي", "uz": "Ibn Hanbalning bunday qilishida qanday manfaati bor,"}, {"ar": "فِعْلِ ذَلِكَ يَا أَبَا الْحَسَنِ؟", "uz": "ey Abu al-Hasan?"}], "full_uz": "Ibn Hanbalning bunday qilishida qanday manfaati bor, ey Abu al-Hasan?", "note": null},
{"num": 473, "time": "00:42:12,260 --> 00:42:19,460", "arabic": "لَا أَدْرِي يَا مَوْلَايَ، وَلَوْلَا أَنَّ الْخَبَرَ سَمِعْتُهُ مِنْكَ لَمَا صَدَّقْتُهُ.", "segs": [{"ar": "لَا أَدْرِي يَا مَوْلَايَ،", "uz": "Bilmayman, xo'jayinim,"}, {"ar": "وَلَوْلَا أَنَّ الْخَبَرَ سَمِعْتُهُ مِنْكَ لَمَا صَدَّقْتُهُ.", "uz": "agar bu xabarni sizdan eshitmaganimda, unga ishonmagan bo'lardim."}], "full_uz": "Bilmayman, xo'jayinim, agar bu xabarni sizdan eshitmaganimda, unga ishonmagan bo'lardim.", "note": null},
{"num": 475, "time": "00:42:19,460 --> 00:42:32,440", "arabic": "فَمَا مَصْلَحَةُ أَبِي عَبْدِ اللَّهِ فِي فِعْلِ ذَلِكَ؟ إِنَّ قَدَمَهُ الْأُولَى فِي الدُّنْيَا وَالْأُخْرَى تُعَانِقُ الْقَبْرَ، وَلَمْ أَعْلَمْ مِنْ سِيرَتِهِ مَا يَحْمِلُهُ عَلَى ذَلِكَ.", "segs": [{"ar": "فَمَا مَصْلَحَةُ أَبِي عَبْدِ اللَّهِ فِي", "uz": "Abu Abdullohning bunday qilishida qanday manfaati bor?"}, {"ar": "فِعْلِ ذَلِكَ؟ إِنَّ قَدَمَهُ الْأُولَى فِي الدُّنْيَا", "uz": "Uning bir oyog'i dunyoda,"}, {"ar": "وَالْأُخْرَى تُعَانِقُ الْقَبْرَ،", "uz": "ikkinchisi qabrni quchoqlab turibdi,"}, {"ar": "وَلَمْ أَعْلَمْ مِنْ سِيرَتِهِ مَا يَحْمِلُهُ عَلَى ذَلِكَ.", "uz": "va uning siyratidan uni bunga undaydigan hech narsani bilmayman."}], "full_uz": "Abu Abdullohning bunday qilishida qanday manfaati bor? Uning bir oyog'i dunyoda, ikkinchisi qabrni quchoqlab turibdi, va uning siyratidan uni bunga undaydigan hech narsani bilmayman.", "note": null},
{"num": 478, "time": "00:42:49,019 --> 00:43:06,359", "arabic": "رُبَّمَا كَانَتْ سَنَوَاتُ الْقَهْرِ الَّتِي لَقِيَهَا مِنْ بَعْضِ أَهْلِي حَمَلَتْهُ عَلَى إِلْقَاءِ الْمَوَدَّةِ إِلَى الطَّالِبِيِّينَ، وَأَنْتَ تَعْلَمُ أَنَّ هَؤُلَاءِ الْقَوْمَ مَا زَالُوا سَاعِينَ إِلَى الْخِلَافِ مُنْذُ أَنْ خَرَجَ جَدُّهُمْ عَلَى بَنِي أُمَيَّةَ، وَكَانُوا حُلَفَاءَ لَهُ.", "segs": [{"ar": "رُبَّمَا كَانَتْ سَنَوَاتُ الْقَهْرِ الَّتِي لَقِيَهَا مِنْ بَعْضِ أَهْلِي حَمَلَتْهُ عَلَى إِلْقَاءِ الْمَوَدَّةِ إِلَى الطَّالِبِيِّينَ،", "uz": "Balki uning mening oilamning ba'zilaridan ko'rgan yillar davomidagi zulmi uni Tolibiylarga muhabbat izhor qilishga undagandir,"}, {"ar": "وَأَنْتَ تَعْلَمُ أَنَّ هَؤُلَاءِ الْقَوْمَ مَا زَالُوا سَاعِينَ إِلَى الْخِلَافِ", "uz": "va bilasizki, bu qavm xalifalikka intilishni davom ettirib kelmoqda,"}, {"ar": "مُنْذُ أَنْ خَرَجَ جَدُّهُمْ عَلَى بَنِي أُمَيَّةَ، وَكَانُوا حُلَفَاءَ لَهُ.", "uz": "buvalari Bani Umayyaga qarshi chiqqanidan beri, va ular unga ittifoqdosh bo'lishgan edi."}], "full_uz": "Balki uning mening oilamning ba'zilaridan ko'rgan yillar davomidagi zulmi uni Tolibiylarga muhabbat izhor qilishga undagandir, va bilasizki, bu qavm buvalari Bani Umayyaga qarshi chiqqanidan beri xalifalikka intilishni davom ettirib kelmoqda, va ular unga ittifoqdosh bo'lishgan edi.", "note": null},
{"num": 483, "time": "00:43:06,359 --> 00:43:09,599", "arabic": "لَا أَدْرِي يَا مَوْلَايَ.", "segs": null, "full_uz": "Bilmayman, xo'jayinim.", "note": null},
{"num": 484, "time": "00:43:09,599 --> 00:43:33,660", "arabic": "لَوْ كَانَ أَحْمَدُ بْنُ حَنْبَلٍ يُقْدِمُ عَلَى خُطْوَةٍ كَهَذِهِ، لَكَانَ أَقْدَمَ عَلَيْهَا يَوْمَ أَنْ كَانَتِ الْمِحْنَةُ فِي أَوْجِهَا، وَكَانَ الْقَهْرُ الْوَاقِعُ عَلَيْهِ أَشَدَّ، وَهُوَ فِي ذَلِكَ الْوَقْتِ لَمْ يَرَ الْخُرُوجَ عَلَى وَلِيِّ الْأَمْرِ إِلَّا مُخَالَفَةً لِلسُّنَّةِ، فَكَيْفَ يُخَالِفُ الْآنَ السُّنَّةَ وَهُوَ يَرَى أَمِيرَ الْمُؤْمِنِينَ مِنْ أَشَدِّ الْمُنْتَصِرِينَ لَهَا؟", "segs": [{"ar": "لَوْ كَانَ أَحْمَدُ بْنُ حَنْبَلٍ يُقْدِمُ عَلَى خُطْوَةٍ كَهَذِهِ،", "uz": "Agar Ahmad ibn Hanbal shunday qadamga qadam qo'yadigan bo'lsa,"}, {"ar": "لَكَانَ أَقْدَمَ عَلَيْهَا يَوْمَ أَنْ كَانَتِ الْمِحْنَةُ فِي أَوْجِهَا، وَكَانَ الْقَهْرُ الْوَاقِعُ عَلَيْهِ أَشَدَّ،", "uz": "sinov o'z cho'qqisida bo'lgan va unga bo'lgan zulm eng shiddatli bo'lgan kunda qadam qo'ygan bo'lardi,"}, {"ar": "وَهُوَ فِي ذَلِكَ الْوَقْتِ لَمْ يَرَ الْخُرُوجَ عَلَى وَلِيِّ الْأَمْرِ إِلَّا مُخَالَفَةً لِلسُّنَّةِ،", "uz": "o'sha vaqtda u rahbarga qarshi chiqishni sunnatga zid deb bilgan edi,"}, {"ar": "فَكَيْفَ يُخَالِفُ الْآنَ السُّنَّةَ وَهُوَ يَرَى أَمِيرَ الْمُؤْمِنِينَ مِنْ أَشَدِّ الْمُنْتَصِرِينَ لَهَا؟", "uz": "xo'sh, hozir mo'minlar amirini sunnatning eng qattiq himoyachilaridan deb bilib turib, sunnatga qanday zid keladi?"}], "full_uz": "Agar Ahmad ibn Hanbal shunday qadamga qadam qo'yadigan bo'lsa, sinov o'z cho'qqisida bo'lgan va unga bo'lgan zulm eng shiddatli bo'lgan kunda qadam qo'ygan bo'lardi. O'sha vaqtda u rahbarga qarshi chiqishni sunnatga zid deb bilgan edi, xo'sh, hozir mo'minlar amirini sunnatning eng qattiq himoyachilaridan biri deb bilib turib, sunnatga qanday zid keladi?", "note": null},
{"num": 490, "time": "00:43:33,660 --> 00:43:38,900", "arabic": "إِنَّ فِي الْأَمْرِ شَيْئًا لَا أُبْصِرُهُ يَا مَوْلَايَ.", "segs": null, "full_uz": "Bu ishda men ko'rmayotgan bir narsa bor, xo'jayinim.", "note": null},
{"num": 491, "time": "00:43:38,900 --> 00:43:55,639", "arabic": "عُيُونُنَا تَقُولُ إِنَّ الْخَبَرَ أَكِيدٌ يَا أَبَا الْحَسَنِ، وَأَنَّ الرَّجُلَ الطَّالِبِيَّ مَا زَالَ مُتَخَفِّيًا فِي بَيْتِ أَحْمَدَ، وَأَحْمَدُ يُبَايَعُ عَلَيْهِ فِي السِّرِّ.", "segs": [{"ar": "عُيُونُنَا تَقُولُ إِنَّ الْخَبَرَ أَكِيدٌ يَا أَبَا الْحَسَنِ،", "uz": "Ko'zchilarimiz xabar aniqligini aytishmoqda, ey Abu al-Hasan,"}, {"ar": "وَأَنَّ الرَّجُلَ الطَّالِبِيَّ مَا", "uz": "va Tolibiy odam hali ham Ahmadning uyida yashiringan,"}, {"ar": "زَالَ مُتَخَفِّيًا فِي بَيْتِ أَحْمَدَ،", "uz": "va Ahmad"}, {"ar": "وَأَحْمَدُ يُبَايَعُ عَلَيْهِ فِي السِّرِّ.", "uz": "unga maxfiy ravishda bay'at oldirmoqda."}], "full_uz": "Ko'zchilarimiz xabar aniqligini aytishmoqda, ey Abu al-Hasan, va Tolibiy odam hali ham Ahmadning uyida yashiringan, va Ahmad unga maxfiy ravishda bay'at oldirmoqda.", "note": null},
{"num": 494, "time": "00:43:55,639 --> 00:43:59,679", "arabic": "لَا يَجْرُؤُ أَحَدٌ عَلَى الْكَذِبِ عَلَى أَمِيرِ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Mo'minlar amiriga hech kim yolg'on gapirishga jur'at eta olmaydi.", "note": null}
];

